 s.modules={...clone(SEED.modules),...(s.modules||{})};
 s.modules.wishlist={...clone(SEED.modules.wishlist),...(s.modules.wishlist||{})};
 s.modules.wishlist.items=Array.isArray(s.modules.wishlist.items)?s.modules.wishlist.items:[];
 s.modules.wishlist.defaultCooldownDays=Math.max(0,Number(s.modules.wishlist.defaultCooldownDays??7));
 s.modules.calendar={...clone(SEED.modules.calendar),...(s.modules.calendar||{})};
