 s.modules.calendar.visibleMonth=/^\d{4}-\d{2}$/.test(s.modules.calendar.visibleMonth||'')?s.modules.calendar.visibleMonth:monthNow();
 s.modules.calendar.selectedDate=/^\d{4}-\d{2}-\d{2}$/.test(s.modules.calendar.selectedDate||'')?s.modules.calendar.selectedDate:today();
 s.modules.brain={...clone(SEED.modules.brain),...(s.modules.brain||{})};
 for(const key of ['sudoku','freecell','minesweeper']){
   s.modules.brain[key]={...clone(SEED.modules.brain[key]),...(s.modules.brain[key]||{})};
   s.modules.brain[key].stats={...clone(SEED.modules.brain[key].stats),...(s.modules.brain[key].stats||{})};
   s.modules.brain[key].history=Array.isArray(s.modules.brain[key].history)?s.modules.brain[key].history:[];
 }
 s.modules.brain.minesweeper.stats.bestSeconds={...clone(SEED.modules.brain.minesweeper.stats.bestSeconds),...(s.modules.brain.minesweeper.stats.bestSeconds||{})};
 s.modules.brain.freecell.autoCollect=s.modules.brain.freecell.autoCollect!==false;
 if(!['sudoku','freecell','minesweeper'].includes(s.modules.brain.activeGame))s.modules.brain.activeGame='sudoku';
 s.modules.tamagotchi={...clone(SEED.modules.tamagotchi),...(s.modules.tamagotchi||{})};
 const petSeedResidents=clone(SEED.modules.tamagotchi.residents),oldResidents=Array.isArray(s.modules.tamagotchi.residents)?s.modules.tamagotchi.residents:[];
 s.modules.tamagotchi.residents=petSeedResidents.map(def=>({...def,...(oldResidents.find(x=>x.id===def.id)||{})})).concat(oldResidents.filter(x=>!petSeedResidents.some(d=>d.id===x.id)));
 s.modules.tamagotchi.history=Array.isArray(s.modules.tamagotchi.history)?s.modules.tamagotchi.history:[];
 s.modules.tamagotchi.memorials=Array.isArray(s.modules.tamagotchi.memorials)?s.modules.tamagotchi.memorials:[];
 s.modules.tamagotchi.scene=['forest','home','meadow','village'].includes(s.modules.tamagotchi.scene)?s.modules.tamagotchi.scene:'forest';
 s.modules.tamagotchi.decorCoins=Math.max(0,Number(s.modules.tamagotchi.decorCoins||0));
 s.modules.tamagotchi.decorUnlocked=Array.isArray(s.modules.tamagotchi.decorUnlocked)?s.modules.tamagotchi.decorUnlocked:['flower-yellow','mushroom-red'];
 s.modules.tamagotchi.decorPlacements=(s.modules.tamagotchi.decorPlacements&&typeof s.modules.tamagotchi.decorPlacements==='object'&&!Array.isArray(s.modules.tamagotchi.decorPlacements))?s.modules.tamagotchi.decorPlacements:{};
 for(const scene of ['forest','home','meadow','village']) if(!Array.isArray(s.modules.tamagotchi.decorPlacements[scene])) s.modules.tamagotchi.decorPlacements[scene]=[];
 s.modules.tamagotchi.decorInitializedScenes=(s.modules.tamagotchi.decorInitializedScenes&&typeof s.modules.tamagotchi.decorInitializedScenes==='object'&&!Array.isArray(s.modules.tamagotchi.decorInitializedScenes))?s.modules.tamagotchi.decorInitializedScenes:{};
