async function loadState(){db=await openDB();const primary=await idbGet('state','current').catch(()=>null);let mirror=null;try{mirror=JSON.parse(localStorage.getItem(MIRROR_KEY)||'null')}catch{};const choices=[primary,mirror].filter(Boolean).map(migrate);state=choices.sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0]||clone(SEED);await persist('启动同步',false,false)}
function backupPayload(){return {app:APP_ID,schemaVersion:12,exportedAt:nowISO(),data:clone(state)}}
function downloadBackup(label='手动备份'){const payload=JSON.stringify(backupPayload(),null,2);const blob=new Blob([payload],{type:'application/json;charset=utf-8'});const u=URL.createObjectURL(blob);const a=document.createElement('a');const d=new Date();const stamp=`${today()}_${String(d.getHours()).padStart(2,'0')}${String(d.getMinutes()).padStart(2,'0')}`;a.href=u;a.download=`小松鼠生活管家_${stamp}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);toast(`${label}已生成`)}
async function persist(reason='保存',userAction=true,makeSnapshot=true){state.app=APP_ID;state.schemaVersion=12;state.updatedAt=nowISO();let shouldDownload=false;if(userAction){const day=today();if(state.settings.everyChangeDownload)shouldDownload=true;else if(state.settings.autoDailyDownload&&state.settings.lastExternalBackupDay!==day)shouldDownload=true;if(shouldDownload){state.settings.lastExternalBackupDay=day;state.settings.lastExternalBackupAt=nowISO();downloadBackup(state.settings.everyChangeDownload?'修改备份':'今日自动备份')}}
 localStorage.setItem(MIRROR_KEY,JSON.stringify(state));await idbPut('state',clone(state),'current');if(makeSnapshot){const snap={id:`${Date.now()}-${Math.random()}`,at:nowISO(),reason,data:clone(state)};await idbPut('snapshots',snap);const all=(await idbAll('snapshots')).sort((a,b)=>String(b.at).localeCompare(String(a.at)));for(const old of all.slice(50))await idbDelete('snapshots',old.id)}renderAll()}
function daysSince(s){if(!s)return null;const d=new Date(`${s}T00:00:00`);const n=new Date();const t=new Date(n.getFullYear(),n.getMonth(),n.getDate());return Math.max(0,Math.floor((t-d)/86400000))}
function urgency(c){const d=daysSince(c.lastDone);return d===null?Infinity:d/Math.max(1,Number(c.interval))}
function choreStatus(c){const u=urgency(c);if(!Number.isFinite(u))return {key:'never',text:'未记录'};if(u>=1)return {key:'due',text:'优先打扫'};if(u>=.75)return {key:'soon',text:'快到期'};return {key:'ok',text:'暂时不用'}}
function selectedMonth(){return $('#ledgerMonth').value||monthNow()}
function monthRecords(){return state.ledger.records.filter(r=>r.date?.startsWith(selectedMonth()))}
function renderHome(){const m=monthRecords();const exp=m.filter(r=>r.type==='支出').reduce((s,r)=>s+Number(r.amount),0);const inc=m.filter(r=>r.type==='收入').reduce((s,r)=>s+Number(r.amount),0);const budget=Object.values(state.ledger.budgets).reduce((s,v)=>s+Number(v),0);const due=state.chores.items.filter(c=>['due','never'].includes(choreStatus(c).key)).length;$('#homeKpis').innerHTML=[['本月支出',money(exp),`${m.filter(r=>r.type==='支出').length}笔支出`],['预算剩余',money(budget-exp),`月预算 ${money(budget)}`],['需要处理的家务',due,`共 ${state.chores.items.length} 项`],['外部备份',state.settings.lastExternalBackupAt?'已建立':'尚未建立',state.settings.lastExternalBackupAt?new Date(state.settings.lastExternalBackupAt).toLocaleString('zh-CN'):'请先点一次立即备份']].map(x=>`<article class="panel card kpi-card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="sub">${x[2]}</div></article>`).join('');const top=[...state.chores.items].sort((a,b)=>urgency(b)-urgency(a))[0];$('#homeChore').innerHTML=top?`<div class="quick-row"><div class="quick-main"><div class="quick-title">${esc(top.icon)} ${esc(top.name)}</div><div class="quick-note">上次：${top.lastDone||'未记录'}｜周期：${top.interval}天</div></div><span class="tag ${choreStatus(top).key}">${choreStatus(top).text}</span></div>`:'<div class="empty">还没有家务任务。</div>';$('#homeLedger').innerHTML=[...state.ledger.records].sort((a,b)=>(b.date+b.updatedAt).localeCompare(a.date+a.updatedAt)).slice(0,5).map(r=>`<div class="quick-row"><div class="quick-main"><div class="quick-title">${esc(r.note||r.category)}</div><div class="quick-note">${esc(r.date)} · ${esc(r.category)}</div></div><div class="money ${r.type==='支出'?'expense':r.type==='收入'?'income':'transfer'}">${r.type==='支出'?'−':r.type==='收入'?'+':'↔'}${money(r.amount)}</div></div>`).join('')||'<div class="empty">还没有账目。</div>'}


/* 日历计划本 */
function calendarData(){return state.modules.calendar}
function calendarEntry(date,create=false){const C=calendarData();let e=C.entries[date];if(!e&&create){e={date,label:'',note:'',todos:[],createdAt:nowISO(),updatedAt:nowISO()};C.entries[date]=e}if(e){e.todos=Array.isArray(e.todos)?e.todos:[];e.label=String(e.label||'');e.note=String(e.note||'')}return e||null}
function calendarDateLabel(date){const d=new Date(`${date}T00:00:00`);return new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(d)}
function calendarShiftMonth(month,delta){const [y,m]=month.split('-').map(Number),d=new Date(y,m-1+delta,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function calendarMonthDates(month){const [y,m]=month.split('-').map(Number),days=new Date(y,m,0).getDate(),first=new Date(y,m-1,1).getDay(),leading=(first+6)%7;return {days,leading}}
function calendarSelected(){const C=calendarData();if(!/^\d{4}-\d{2}-\d{2}$/.test(C.selectedDate||''))C.selectedDate=today();return C.selectedDate}
function calendarCaptureEditor(){const label=$('#calendarLabel'),note=$('#calendarNote');if(!label||!note)return;const date=calendarSelected(),old=calendarEntry(date),labelText=label.value.trim(),noteText=note.value.trim();if(!old&&!labelText&&!noteText)return;const e=calendarEntry(date,true);e.label=labelText;e.note=noteText;e.updatedAt=nowISO();if(!e.label&&!e.note&&!e.todos.length)delete calendarData().entries[date]}
function calendarPendingCount(entry){return entry?.todos?.filter(t=>!t.done).length||0}
function renderCalendarHome(){const C=calendarData(),todayEntry=calendarEntry(today()),todayPending=calendarPendingCount(todayEntry),future=Object.values(C.entries||{}).flatMap(e=>(e.todos||[]).filter(t=>!t.done).map(t=>({date:e.date,text:t.text}))).filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date));const el=$('#homeCalendarSummary');if(el)el.textContent=todayEntry?.label?`今天：${todayEntry.label}${todayPending?`，还有 ${todayPending} 项待办`:''}`:future.length?`下一项：${future[0].date} · ${future[0].text}`:'记录今天做了什么，也把之后的计划安稳放进日历。'}
function renderCalendar(){const C=calendarData();if(!/^\d{4}-\d{2}$/.test(C.visibleMonth||''))C.visibleMonth=monthNow();const month=C.visibleMonth,selected=calendarSelected(),{days,leading}=calendarMonthDates(month),entries=C.entries||{};$('#calendarMonth').value=month;const monthEntries=Object.values(entries).filter(e=>e.date?.startsWith(month)),recorded=monthEntries.filter(e=>e.label||e.note).length,pending=Object.values(entries).reduce((n,e)=>n+(e.todos||[]).filter(t=>!t.done).length,0),done=Object.values(entries).reduce((n,e)=>n+(e.todos||[]).filter(t=>t.done).length,0);$('#calendarKpis').innerHTML=[['本月有记录',`${recorded}天`,'写过标注或日记'],['未完成计划',pending,'所有日期合计'],['已经完成',done,'打勾也算生活痕迹'],['当前查看',month,selected===today()?'选中今天':`选中 ${selected.slice(5)}`]].map(x=>`<article class="panel card kpi-card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="sub">${x[2]}</div></article>`).join('');let cells=Array.from({length:leading},()=>'<button class="calendar-day empty" tabindex="-1"></button>');for(let day=1;day<=days;day++){const date=`${month}-${String(day).padStart(2,'0')}`,e=entries[date],pendingDay=calendarPendingCount(e),doneDay=e?.todos?.filter(t=>t.done).length||0,meta=[];if(e?.note)meta.push('<span class="calendar-dot note" title="有日记"></span>');if(pendingDay)meta.push(`<span class="calendar-dot todo"></span><span class="calendar-count">${pendingDay}待办</span>`);else if(doneDay)meta.push('<span class="calendar-dot done" title="待办已完成"></span>');cells.push(`<button class="calendar-day ${date===today()?'today':''} ${date===selected?'selected':''}" data-calendar-date="${date}"><span class="calendar-day-number">${day}</span>${e?.label?`<span class="calendar-day-label">${esc(e.label)}</span>`:''}<span class="calendar-day-meta">${meta.join('')}</span></button>`)}$('#calendarGrid').innerHTML=cells.join('');renderCalendarDetail();renderCalendarUpcoming();renderCalendarHome()}
function renderCalendarDetail(){const date=calendarSelected(),e=calendarEntry(date);$('#calendarSelectedTitle').textContent=calendarDateLabel(date);$('#calendarSelectedSub').textContent=date===today()?'今天的小窝记录':date<today()?'可以补写这一天发生的事':'可以提前安排这一天';$('#calendarLabel').value=e?.label||'';$('#calendarNote').value=e?.note||'';$('#calendarTodoList').innerHTML=(e?.todos||[]).map(t=>`<div class="calendar-todo ${t.done?'done':''}" data-calendar-todo="${t.id}"><input type="checkbox" data-calendar-todo-toggle="${t.id}" ${t.done?'checked':''} aria-label="完成待办"><div class="calendar-todo-main">${esc(t.text)}<small>${t.done&&t.completedAt?`完成于 ${new Date(t.completedAt).toLocaleString('zh-CN')}`:'尚未完成'}</small></div><button class="calendar-todo-delete" data-calendar-todo-delete="${t.id}" aria-label="删除">×</button></div>`).join('')||'<div class="empty" style="padding:24px 8px">这一天还没有待办。</div>'}
function renderCalendarUpcoming(){const rows=Object.values(calendarData().entries||{}).flatMap(e=>(e.todos||[]).filter(t=>!t.done).map(t=>({date:e.date,id:t.id,text:t.text,label:e.label||''}))).filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,12);$('#calendarUpcoming').innerHTML=rows.map(x=>`<div class="calendar-upcoming-row"><div class="calendar-upcoming-main"><strong>${esc(x.text)}</strong><small>${esc(x.date)}${x.label?` · ${esc(x.label)}`:''}</small></div><button class="btn ghost" data-calendar-jump="${x.date}">查看</button></div>`).join('')||'<div class="empty">接下来没有未完成计划，小松鼠的日程很轻盈。</div>'}
async function selectCalendarDate(date,save=true){calendarCaptureEditor();const C=calendarData();C.selectedDate=date;C.visibleMonth=date.slice(0,7);if(save)await persist('切换日历日期',false,false);else renderCalendar()}
async function saveCalendarDay(){const date=calendarSelected(),e=calendarEntry(date,true);e.label=$('#calendarLabel').value.trim();e.note=$('#calendarNote').value.trim();e.updatedAt=nowISO();if(!e.label&&!e.note&&!e.todos.length)delete calendarData().entries[date];await persist(`保存日历：${date}`,true,true);toast('这一天已经收进日历本')}
async function addCalendarTodo(){calendarCaptureEditor();const text=$('#calendarTodoInput').value.trim();if(!text)return toast('先写下要做的事情');const date=calendarSelected(),e=calendarEntry(date,true);e.todos.push({id:uid('todo'),text,done:false,createdAt:nowISO(),completedAt:''});e.updatedAt=nowISO();$('#calendarTodoInput').value='';await persist(`添加待办：${date}`,true,true)}
async function toggleCalendarTodo(id){calendarCaptureEditor();const date=calendarSelected(),e=calendarEntry(date);if(!e)return;const t=e.todos.find(x=>x.id===id);if(!t)return;t.done=!t.done;t.completedAt=t.done?nowISO():'';e.updatedAt=nowISO();await persist(`${t.done?'完成':'恢复'}待办：${t.text}`,true,true)}
async function deleteCalendarTodo(id){calendarCaptureEditor();const date=calendarSelected(),e=calendarEntry(date);if(!e)return;const t=e.todos.find(x=>x.id===id);if(!t||!confirm(`删除待办“${t.text}”吗？`))return;e.todos=e.todos.filter(x=>x.id!==id);e.updatedAt=nowISO();if(!e.label&&!e.note&&!e.todos.length)delete calendarData().entries[date];await persist(`删除待办：${date}`,true,true)}

function renderLedger(){const records=monthRecords();const expenses=records.filter(r=>r.type==='支出');const incomes=records.filter(r=>r.type==='收入');const exp=expenses.reduce((s,r)=>s+Number(r.amount),0),inc=incomes.reduce((s,r)=>s+Number(r.amount),0),budget=Object.values(state.ledger.budgets).reduce((s,v)=>s+Number(v),0);$('#ledgerKpis').innerHTML=[['月度预算',money(budget),'五个预算池合计'],['本月支出',money(exp),`${expenses.length}笔`],['本月收入',money(inc),`${incomes.length}笔`],['预算剩余',money(budget-exp),`已使用 ${budget?((exp/budget)*100).toFixed(1):0}%`]].map(x=>`<article class="panel card kpi-card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="sub">${x[2]}</div></article>`).join('');$('#budgetGrid').innerHTML=Object.entries(state.ledger.budgets).map(([name,val])=>{const spent=expenses.filter(r=>r.pool===name).reduce((s,r)=>s+Number(r.amount),0);const rate=val?spent/val:0;return `<div class="budget ${rate>1?'over':''}"><div class="budget-name">${esc(name)}</div><div class="budget-meta"><span>已用 ${money(spent)}</span><span>${money(val)}</span></div><div class="bar"><span style="width:${Math.min(100,rate*100)}%"></span></div><div class="sub">${rate>1?`超出 ${money(spent-val)}`:`剩余 ${money(val-spent)}`}</div></div>`}).join('');renderChart('#categoryChart',group(expenses,r=>r.category));renderChart('#dailyChart',group(expenses,r=>r.date),true);let filtered=records;const tf=$('#ledgerTypeFilter').value,pf=$('#ledgerPoolFilter').value,q=$('#ledgerSearch').value.trim().toLowerCase();filtered=filtered.filter(r=>(!tf||r.type===tf)&&(!pf||r.pool===pf)&&(`${r.category} ${r.note} ${r.account} ${r.pool}`.toLowerCase().includes(q))).sort((a,b)=>(b.date+b.updatedAt).localeCompare(a.date+a.updatedAt));$('#recordCount').textContent=`${filtered.length}笔`;$('#recordList').innerHTML=filtered.map(r=>`<article class="record"><div class="record-main"><div class="record-title">${esc(r.category)} · ${esc(r.note||'无备注')}</div><div class="record-note">${esc(r.type)}｜${esc(r.pool||r.type)}｜${esc(r.nature||'—')}</div></div><div><div class="meta-label">日期</div><div class="meta-value">${esc(r.date)}</div></div><div><div class="meta-label">账户</div><div class="meta-value">${esc(r.account)}</div></div><div><div class="money ${r.type==='支出'?'expense':r.type==='收入'?'income':'transfer'}">${r.type==='支出'?'−':r.type==='收入'?'+':'↔'}${money(r.amount)}</div><div class="actions"><button class="icon-btn" data-ledger-action="edit" data-id="${r.id}">编辑</button><button class="icon-btn" data-ledger-action="copy" data-id="${r.id}">复制</button><button class="icon-btn" data-ledger-action="delete" data-id="${r.id}">删除</button></div></div></article>`).join('')||'<div class="empty">没有符合条件的账目。</div>'}
function group(arr,keyFn){const m={};arr.forEach(r=>{const k=keyFn(r)||'其他';m[k]=(m[k]||0)+Number(r.amount||0)});return m}
function renderChart(sel,map,sortByValue=false){let entries=Object.entries(map);entries.sort(sortByValue?(a,b)=>b[1]-a[1]:(a,b)=>b[1]-a[1]);entries=entries.slice(0,10);const max=Math.max(1,...entries.map(x=>x[1]));$(sel).innerHTML=entries.map(([k,v])=>`<div class="chart-row"><div class="chart-label">${esc(k)}</div><div class="chart-track"><span style="width:${v/max*100}%"></span></div><div class="chart-value">${money(v)}</div></div>`).join('')||'<div class="empty">暂无支出数据。</div>'}
function renderChores(){const q=$('#choreSearch').value.trim().toLowerCase(),filter=$('#choreFilter').value;const items=[...state.chores.items].filter(c=>(!q||`${c.name} ${c.note}`.toLowerCase().includes(q))&&(!filter||choreStatus(c).key===filter)).sort((a,b)=>urgency(b)-urgency(a));$('#choreList').innerHTML=items.map(c=>{const d=daysSince(c.lastDone),st=choreStatus(c);return `<article class="chore"><div class="chore-main"><div class="chore-title">${esc(c.icon)} ${esc(c.name)}</div><div class="chore-note">${esc(c.note||'暂无备注')}</div></div><div><div class="meta-label">上次完成</div><div class="meta-value">${c.lastDone||'未记录'}</div></div><div><div class="meta-label">已经过去 / 周期</div><div class="meta-value">${d===null?'—':d+'天'} / ${c.interval}天</div></div><div><span class="tag ${st.key}">${st.text}</span><div class="actions" style="margin-top:8px"><button class="icon-btn done" data-chore-action="done" data-id="${c.id}">刚刚完成</button><button class="icon-btn" data-chore-action="edit" data-id="${c.id}">编辑</button><button class="icon-btn" data-chore-action="delete" data-id="${c.id}">删除</button></div></div></article>`}).join('')||'<div class="empty">没有符合条件的家务。</div>'}

function wishlistData(){return state.modules.wishlist}
function localDate(s){if(!s)return null;const p=String(s).split('-').map(Number);if(p.length!==3||p.some(x=>!Number.isFinite(x)))return null;return new Date(p[0],p[1]-1,p[2])}
function dateString(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function addDateDays(s,n){const d=localDate(s)||localDate(today());d.setDate(d.getDate()+Number(n||0));return dateString(d)}
function dayDiff(a,b){const d1=localDate(a),d2=localDate(b);if(!d1||!d2)return 0;return Math.round((d2-d1)/86400000)}
function wishPhase(w){if(w.status==='bought')return'bought';if(w.status==='skipped')return'skipped';return String(w.decisionDate||'')<=today()?'ready':'cooling'}
function wishStatusInfo(w){const p=wishPhase(w);return {phase:p,label:p==='cooling'?'冷静中':p==='ready'?'可以决定':p==='bought'?'已买下':'已放弃'}}
function safeWishUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return''}}
function normalizeWishItem(w){w.status=['pending','bought','skipped'].includes(w.status)?w.status:'pending';w.addedDate=w.addedDate||today();w.coolingStartDate=w.coolingStartDate||w.addedDate;w.cooldownDays=Math.max(0,Number(w.cooldownDays??7));w.decisionDate=w.decisionDate||addDateDays(w.coolingStartDate,w.cooldownDays);w.price=Math.max(0,Number(w.price||0));return w}
function renderWishlistHome(){const el=$('#homeWishSummary');if(!el)return;const items=wishlistData().items.map(normalizeWishItem),active=items.filter(w=>['cooling','ready'].includes(wishPhase(w))),ready=active.filter(w=>wishPhase(w)==='ready');el.textContent=active.length?`${active.length}件仍在考虑，其中${ready.length}件已经可以决定。`:'目前没有等待决定的愿望。'}
function renderWishlist(){const W=wishlistData();W.items=W.items.map(normalizeWishItem);const q=$('#wishSearch').value.trim().toLowerCase(),status=$('#wishStatusFilter').value,pool=$('#wishPoolFilter').value,sort=$('#wishSort').value;const all=W.items;const active=all.filter(w=>['cooling','ready'].includes(wishPhase(w))),ready=all.filter(w=>wishPhase(w)==='ready'),skipped=all.filter(w=>wishPhase(w)==='skipped'),bought=all.filter(w=>wishPhase(w)==='bought');$('#wishKpis').innerHTML=[['等待决定',`${active.length}件`,money(active.reduce((s,w)=>s+w.price,0))],['现在可决定',`${ready.length}件`,'冷静期已经结束'],['已经忍住',money(skipped.reduce((s,w)=>s+w.price,0)),`${skipped.length}件已放弃`],['已经买下',money(bought.reduce((s,w)=>s+w.price,0)),`${bought.length}件`]].map(x=>`<article class="panel card kpi-card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div><div class="sub">${x[2]}</div></article>`).join('');let items=all.filter(w=>{const phase=wishPhase(w),hay=`${w.name||''} ${w.reason||''} ${w.pool||''} ${w.category||''}`.toLowerCase();return(!q||hay.includes(q))&&(!status||phase===status)&&(!pool||w.pool===pool)});items.sort((a,b)=>{if(sort==='newest')return String(b.createdAt||b.addedDate).localeCompare(String(a.createdAt||a.addedDate));if(sort==='priceDesc')return b.price-a.price;if(sort==='priceAsc')return a.price-b.price;const order={ready:0,cooling:1,bought:2,skipped:3},pa=wishPhase(a),pb=wishPhase(b);return order[pa]-order[pb]||String(a.decisionDate||a.outcomeDate||'').localeCompare(String(b.decisionDate||b.outcomeDate||''))});$('#wishList').innerHTML=items.map(w=>{const st=wishStatusInfo(w),link=safeWishUrl(w.link),ledgerExists=!!state.ledger.records.find(r=>r.id===w.ledgerRecordId);let progress=100,detail='';if(st.phase==='cooling'){const total=Math.max(1,dayDiff(w.coolingStartDate,w.decisionDate)),passed=Math.max(0,dayDiff(w.coolingStartDate,today()));progress=Math.min(100,Math.max(0,passed/total*100));const left=Math.max(1,dayDiff(today(),w.decisionDate));detail=`还需冷静 ${left} 天 · ${w.decisionDate} 可以决定`}else if(st.phase==='ready')detail=`冷静期已结束 · 已等待 ${Math.max(0,dayDiff(w.addedDate,today()))} 天`;else detail=`${w.outcomeDate||'未记录日期'} · ${st.label}`;const activeActions=['cooling','ready'].includes(st.phase)?`<button class="icon-btn primary-action" data-wish-action="buy" data-id="${w.id}">买下</button><button class="icon-btn danger-soft" data-wish-action="skip" data-id="${w.id}">放弃</button><button class="icon-btn" data-wish-action="postpone" data-id="${w.id}">再等7天</button>`:st.phase==='bought'?`${ledgerExists?'<button class="icon-btn" disabled>已记账</button>':`<button class="icon-btn primary-action" data-wish-action="record" data-id="${w.id}">记入账本</button>`}<button class="icon-btn" data-wish-action="reopen" data-id="${w.id}">重新考虑</button>`:`<button class="icon-btn" data-wish-action="reopen" data-id="${w.id}">重新考虑</button>`;return `<article class="wish-card"><div class="wish-head"><div><div class="wish-title">${esc(w.name)}</div><div class="wish-meta"><span>${esc(w.pool||'未分预算池')}</span><span>·</span><span>${esc(w.category||'其他')}</span><span>·</span><span>加入 ${esc(w.addedDate)}</span></div></div><div class="wish-price">${money(w.price)}</div></div>${w.reason?`<div class="wish-reason">${esc(w.reason)}</div>`:''}<div><div class="wish-foot"><span class="tag ${st.phase}">${st.label}</span><span class="sub" style="margin:0">${esc(detail)}</span></div>${['cooling','ready'].includes(st.phase)?`<div class="wish-progress" style="margin-top:9px"><span style="width:${progress}%"></span></div>`:''}</div><div class="wish-foot">${link?`<a class="wish-link" href="${esc(link)}" target="_blank" rel="noopener">打开商品链接 ↗</a>`:'<span></span>'}<div class="wish-actions">${activeActions}<button class="icon-btn" data-wish-action="edit" data-id="${w.id}">编辑</button><button class="icon-btn" data-wish-action="delete" data-id="${w.id}">删除</button></div></div></article>`}).join('')||'<div class="empty">愿望箱还是空的。先把想买的东西放进来，不急着下单。</div>'}
function openWish(w=null){const W=wishlistData();$('#wishForm').reset();$('#wishEditId').value=w?.id||'';$('#wishDialogTitle').textContent=w?'编辑愿望':'放入新愿望';$('#wishName').value=w?.name||'';$('#wishPrice').value=w?.price||'';$('#wishPool').value=w?.pool||(Object.keys(state.ledger.budgets).includes('临时愿望')?'临时愿望':Object.keys(state.ledger.budgets)[0]);$('#wishCategory').value=w?.category||(state.ledger.categories.includes('其他')?'其他':state.ledger.categories[0]);$('#wishAddedDate').value=w?.addedDate||today();$('#wishCooldownDays').value=w?.cooldownDays??W.defaultCooldownDays??7;$('#wishLink').value=w?.link||'';$('#wishReason').value=w?.reason||'';$('#wishDialog').showModal()}
async function markWishBought(w){if(!confirm(`把“${w.name}”标记为已经买下吗？`))return;w.status='bought';w.outcomeDate=today();w.updatedAt=nowISO();await persist(`买下愿望：${w.name}`,true,true)}
async function skipWish(w){if(!confirm(`确认放弃“${w.name}”吗？这会计入“已经忍住”的金额。`))return;w.status='skipped';w.outcomeDate=today();w.updatedAt=nowISO();await persist(`放弃愿望：${w.name}`,true,true)}
async function postponeWish(w){const base=String(w.decisionDate||'')>today()?w.decisionDate:today();w.status='pending';w.coolingStartDate=today();w.decisionDate=addDateDays(base,7);w.postponedCount=Number(w.postponedCount||0)+1;w.updatedAt=nowISO();await persist(`愿望再冷静7天：${w.name}`,true,true)}
async function reopenWish(w){w.status='pending';w.outcomeDate='';w.coolingStartDate=today();w.cooldownDays=Math.max(0,Number(w.cooldownDays??wishlistData().defaultCooldownDays??7));w.decisionDate=addDateDays(today(),w.cooldownDays);w.updatedAt=nowISO();await persist(`重新考虑愿望：${w.name}`,true,true)}
async function recordWishPurchase(w){if(state.ledger.records.find(r=>r.id===w.ledgerRecordId))return toast('这件愿望已经记过账啦');if(!confirm(`把“${w.name}”的 ${money(w.price)} 记入本月账本吗？`))return;const pool=Object.keys(state.ledger.budgets).includes(w.pool)?w.pool:(Object.keys(state.ledger.budgets)[0]||''),category=state.ledger.categories.includes(w.category)?w.category:(state.ledger.categories.includes('其他')?'其他':state.ledger.categories[0]);const rec={id:uid('ledger'),createdAt:nowISO(),updatedAt:nowISO(),date:today(),type:'支出',pool,category,amount:Number(w.price),account:state.ledger.accounts[0]||'其他',nature:state.ledger.natures.includes('幸福')?'幸福':state.ledger.natures[0],note:`愿望实现：${w.name}`};state.ledger.records.push(rec);w.ledgerRecordId=rec.id;w.updatedAt=nowISO();$('#ledgerMonth').value=today().slice(0,7);await persist(`愿望买下并记账：${w.name}`,true,true)}


