function tamagotchiData(){return state.modules.tamagotchi}
function chinaParts(d=new Date()){const ps=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(d),o={};ps.forEach(x=>{if(x.type!=='literal')o[x.type]=x.value});return o}
function chinaDate(d=new Date()){const p=chinaParts(d);return `${p.year}-${p.month}-${p.day}`}
function chinaHour(d=new Date()){return Number(chinaParts(d).hour||0)}
function chinaClock(){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'long',day:'numeric',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date())}
function isPetNight(){const h=chinaHour();return h<7}
function clampPet(v){return Math.max(0,Math.min(100,Number(v||0)))}
function normalizeTamagotchiPet(p){const born=p.bornAt||nowISO();return {id:p.id||uid('pet'),name:p.name||'团团',emoji:p.emoji||'🐿️',bornAt:born,alive:p.alive!==false,deadAt:p.deadAt||'',hunger:clampPet(p.hunger??82),happiness:clampPet(p.happiness??82),cleanliness:clampPet(p.cleanliness??86),health:clampPet(p.health??100),affection:clampPet(p.affection??20),lastUpdated:p.lastUpdated||nowISO(),daily:{date:p.daily?.date||chinaDate(),fed:!!p.daily?.fed,played:!!p.daily?.played,cleaned:!!p.daily?.cleaned},spouseId:p.spouseId||'',marriedAt:p.marriedAt||'',babyDueDate:p.babyDueDate||'',babyReady:!!p.babyReady,nextBabyDate:p.nextBabyDate||'',children:Array.isArray(p.children)?p.children:[],log:Array.isArray(p.log)?p.log:[]}}
function petAgeDays(p){return Math.max(0,Math.floor((Date.now()-new Date(p.bornAt).getTime())/86400000))}
function petStage(p){const d=petAgeDays(p);if(d<2)return{key:'baby',label:'幼崽',icon:'🍼'};if(d<5)return{key:'child',label:'小朋友',icon:'🧸'};if(d<9)return{key:'teen',label:'少年',icon:'🌱'};if(d<60)return{key:'adult',label:'成年',icon:'🌿'};return{key:'elder',label:'长者',icon:'🍂'}}
function petMood(p){if(!p.alive)return'🕯️';if(isPetNight())return'😴';if(p.health<30)return'🤒';const avg=(p.hunger+p.happiness+p.cleanliness)/3;if(avg>=80)return'😄';if(avg>=55)return'🙂';if(avg>=30)return'😟';return'😭'}
function petHash(s){let h=0;for(const c of String(s))h=(h*31+c.charCodeAt(0))>>>0;return h}
function petLog(p,msg,icon='🐾'){p.log=p.log||[];p.log.unshift({id:uid('petlog'),at:nowISO(),icon,msg});p.log=p.log.slice(0,40)}
function ensurePetDaily(p){const d=chinaDate();if(p.daily?.date!==d){p.daily={date:d,fed:false,played:false,cleaned:false};return true}return false}
function ensurePetEvent(){const T=tamagotchiData(),p=T.current;if(!p?.alive)return false;const d=chinaDate();if(T.event?.date===d||T.lastEventDate===d)return false;const residents=T.residents||[];if(!residents.length)return false;const seed=petHash(`${d}-${p.id}`),template=PET_EVENTS[seed%PET_EVENTS.length],resident=residents[(seed+3)%residents.length];T.event={date:d,templateId:template.id,residentId:resident.id};return true}
function processTamagotchiTime(){const T=tamagotchiData(),p=T.current;if(!p)return false;let changed=false;Object.assign(p,normalizeTamagotchiPet(p));if(!p.alive)return changed;changed=ensurePetDaily(p)||changed;const last=new Date(p.lastUpdated).getTime(),elapsed=Math.max(0,Math.min(120,(Date.now()-last)/3600000));if(elapsed>.03){p.hunger=clampPet(p.hunger-elapsed*1.65);p.happiness=clampPet(p.happiness-elapsed*.48);p.cleanliness=clampPet(p.cleanliness-elapsed*.36);const danger=(p.hunger<18?1:0)+(p.happiness<12?1:0)+(p.cleanliness<15?1:0);if(danger)p.health=clampPet(p.health-elapsed*.9*danger);else if(isPetNight()&&p.hunger>45&&p.cleanliness>40)p.health=clampPet(p.health+elapsed*.12);p.lastUpdated=nowISO();changed=true}
 if(p.spouseId&&p.babyDueDate&&p.babyDueDate<=chinaDate()&&!p.babyReady){p.babyReady=true;petLog(p,'树屋里传来了轻轻的蛋壳声，宝宝就要出生了！','🥚');changed=true}
 if(p.health<=0&&p.alive){p.alive=false;p.deadAt=nowISO();petLog(p,`${p.name}因为长期没有得到照顾，离开了树屋。`,'🕯️');T.memorials.unshift({id:p.id,name:p.name,emoji:p.emoji,bornAt:p.bornAt,deadAt:p.deadAt,ageDays:petAgeDays(p)});T.memorials=T.memorials.slice(0,20);changed=true}
 changed=ensurePetEvent()||changed;return changed}
