function decorStoreItem(id){return DECOR_STORE.find(x=>x.id===id)||null}
function createDecorPlacement(spec={}){return {id:spec.id||uid('decor'),itemId:spec.itemId||'',emoji:spec.emoji||decorStoreItem(spec.itemId)?.emoji||'🌼',name:spec.name||decorStoreItem(spec.itemId)?.name||'',x:Math.max(6,Math.min(94,Number(spec.x??50))),y:Math.max(10,Math.min(92,Number(spec.y??78))),scale:Math.max(.55,Math.min(2.4,Number(spec.scale??1))),z:Number(spec.z??5),preset:!!spec.preset}}
function ensureDecorState(){const T=tamagotchiData();if(!T.decorStarterGranted){T.decorCoins=Math.max(100,Number(T.decorCoins||0));T.decorStarterGranted=true}else T.decorCoins=Math.max(0,Number(T.decorCoins||0));T.decorUnlocked=Array.isArray(T.decorUnlocked)?T.decorUnlocked:['flower-yellow','mushroom-red'];T.decorPlacements=(T.decorPlacements&&typeof T.decorPlacements==='object'&&!Array.isArray(T.decorPlacements))?T.decorPlacements:{};T.decorInitializedScenes=(T.decorInitializedScenes&&typeof T.decorInitializedScenes==='object'&&!Array.isArray(T.decorInitializedScenes))?T.decorInitializedScenes:{};for(const scene of Object.keys(PET_SCENES)){if(!Array.isArray(T.decorPlacements[scene]))T.decorPlacements[scene]=[];if(!T.decorInitializedScenes[scene]){T.decorPlacements[scene]=DECOR_PRESETS[scene].map(createDecorPlacement).concat(T.decorPlacements[scene].map(createDecorPlacement));T.decorInitializedScenes[scene]=true}else T.decorPlacements[scene]=T.decorPlacements[scene].map(createDecorPlacement)}}
function decorSceneList(scene=null){ensureDecorState();return tamagotchiData().decorPlacements[scene||tamagotchiData().scene||'forest']||[]}
function decorSelected(scene=null){const list=decorSceneList(scene);return list.find(x=>x.id===selectedPetDecorId)||null}
function renderPlacedDecor(scene){const edit=petGamePanel==='decor';const items=[...decorSceneList(scene)].sort((a,b)=>a.z-b.z);return `<div class="pet-scene-decor-layer ${edit?'editing':''}">${items.map(d=>`<button class="pet-scene-decor-item ${selectedPetDecorId===d.id?'selected':''}" data-pet-decor-item="${d.id}" style="left:${d.x}%;top:${d.y}%;z-index:${Math.round(d.z)};transform:translate(-50%,-50%) scale(${d.scale})" title="${esc(d.name||d.emoji)}">${d.emoji}</button>`).join('')}</div>`}
function awardDecorCoins(amount,reason=''){const T=tamagotchiData();ensureDecorState();amount=Math.max(0,Number(amount||0));if(!amount)return;T.decorCoins+=amount;if(reason)toast(`获得 ${amount} 积分 · ${reason}`)}
async function buyDecor(itemId){ensureDecorState();const T=tamagotchiData(),item=decorStoreItem(itemId);if(!item)return;if((T.decorUnlocked||[]).includes(itemId))return toast('这个摆设已经买过啦');if(T.decorCoins<item.price)return toast('积分不够，再去玩小游戏赚一点吧');T.decorCoins-=item.price;T.decorUnlocked.push(itemId);await persist(`购买摆设：${item.name}`,true,true)}
async function placeDecor(itemId){ensureDecorState();const T=tamagotchiData(),scene=T.scene||'forest',item=decorStoreItem(itemId);if(!item)return;if(!(T.decorUnlocked||[]).includes(itemId))return toast('要先买下来才可以摆放');const list=decorSceneList(scene),maxZ=Math.max(4,...list.map(x=>Number(x.z||0)));const d=createDecorPlacement({itemId,emoji:item.emoji,name:item.name,x:50+Math.random()*12-6,y:78+Math.random()*8-4,scale:item.scale||1,z:maxZ+1});list.push(d);selectedPetDecorId=d.id;await persist(`摆放摆设：${item.name}`,false,false)}
async function petDecorAction(action){const T=tamagotchiData(),scene=T.scene||'forest',d=decorSelected(scene);if(!d&&action!=='clear-select')return toast('先点一个场景里的摆设');if(action==='front')d.z+=1;else if(action==='back')d.z=Math.max(1,d.z-1);else if(action==='bigger')d.scale=Math.min(2.4,Number(d.scale)+.08);else if(action==='smaller')d.scale=Math.max(.55,Number(d.scale)-.08);else if(action==='delete'){T.decorPlacements[scene]=decorSceneList(scene).filter(x=>x.id!==d.id);selectedPetDecorId=''}else if(action==='clone'){const copy=createDecorPlacement({...d,id:'',x:Math.min(94,d.x+6),y:Math.min(92,d.y+3),z:d.z+1,preset:false});decorSceneList(scene).push(copy);selectedPetDecorId=copy.id}else if(action==='clear-select'){selectedPetDecorId=''}await persist(`调整场景摆设：${action}`,false,false)}
function petTimePhase(){const h=chinaParts().hour;if(h>=5&&h<=10)return {key:'morning',label:'早晨',emoji:'🌤️'};if(h>=11&&h<=16)return {key:'noon',label:'中午',emoji:'☀️'};if(h>=17&&h<=21)return {key:'evening',label:'晚上',emoji:'🌇'};return {key:'night',label:'深夜',emoji:'🌙'}}
function petSkyDecor(phase){
 if(phase==='morning')return `<div class="pet-sky-layer"><div class="pet-cloud" style="left:10%;top:74px"></div><div class="pet-cloud" style="left:32%;top:52px;transform:scale(.82)"></div><div class="pet-sunrise"></div></div>`;
 if(phase==='noon')return `<div class="pet-sky-layer"><div class="pet-cloud" style="left:12%;top:72px"></div><div class="pet-cloud" style="left:34%;top:48px;transform:scale(.88)"></div><div class="pet-cloud" style="right:14%;top:80px;transform:scale(.78)"></div><div class="pet-sun"></div></div>`;
 if(phase==='evening')return `<div class="pet-sky-layer"><div class="pet-cloud" style="left:14%;top:78px;background:rgba(255,231,215,.52)"></div><div class="pet-cloud" style="left:30%;top:50px;background:rgba(255,224,208,.48);transform:scale(.86)"></div><div class="pet-sunrise" style="right:12%;top:46px;opacity:.82;filter:hue-rotate(-18deg) saturate(1.08)"></div></div>`;
 return `<div class="pet-sky-layer"><div class="pet-moon"></div><i class="pet-star big" style="left:18%;top:58px"></i><i class="pet-star" style="left:26%;top:94px"></i><i class="pet-star" style="left:35%;top:46px"></i><i class="pet-star big" style="left:44%;top:76px"></i><i class="pet-star" style="left:52%;top:62px"></i><i class="pet-star" style="right:24%;top:84px"></i><i class="pet-star" style="right:32%;top:54px"></i><i class="pet-star big" style="right:17%;top:102px"></i></div>`}
function petHomeWindowView(phase){
 const daySky = phase==='morning' ? '<div class="pane-sunrise"></div>' : phase==='noon' ? '<div class="pane-sun"></div>' : phase==='evening' ? '<div class="pane-sunrise" style="top:12%;right:10%;opacity:.76;filter:hue-rotate(-22deg) saturate(1.05)"></div>' : '<div class="pane-moon"></div><i class="pane-star" style="left:18%;top:16%"></i><i class="pane-star" style="left:32%;top:30%"></i><i class="pane-star" style="left:48%;top:12%"></i><i class="pane-star" style="right:28%;top:26%"></i><i class="pane-star" style="right:16%;top:14%"></i>';
 const skyClass = phase==='night' ? 'style="background:linear-gradient(#12253d,#1f3653)"' : phase==='evening' ? 'style="background:linear-gradient(#f6c5a0,#f5dfc6)"' : 'style="background:linear-gradient(#d9f1fb,#eefaff)"';
 const landClass = phase==='night' ? 'style="background:linear-gradient(#45624c,#274334)"' : 'style="background:linear-gradient(#9ec183,#80a06b)"';
 const hillClass = phase==='night' ? 'style="background:rgba(57,94,72,.92)"' : '';
 return `<div class="pane-sky" ${skyClass}></div><div class="pane-land" ${landClass}></div><div class="pane-hill" ${hillClass}></div>${daySky}<i class="curtain"></i><i class="curtain2"></i>`}
function petSceneDecor(scene,night){
 const phase=petTimePhase().key;
 const common=`<div class="pet-hill a"></div><div class="pet-hill b"></div><div class="pet-land"></div>${petSkyDecor(phase)}<div class="bush" style="left:6%;bottom:122px;width:76px;height:30px"></div><div class="bush" style="left:18%;bottom:132px;width:58px;height:24px"></div><div class="bush" style="right:10%;bottom:126px;width:88px;height:32px"></div><div class="stone" style="left:44%;bottom:104px;width:34px;height:18px"></div><div class="stone" style="right:28%;bottom:110px;width:24px;height:14px"></div><div class="spark" style="left:48%;top:164px"></div><div class="spark" style="left:54%;top:144px"></div>`;
 if(scene==='home')return `<div class="pet-home-wall"></div><div class="pet-home-window">${petHomeWindowView(phase)}</div><div class="pet-rug"></div><div class="pet-big-bed"></div><div class="pet-side-table left"></div><div class="pet-side-table right"></div><div class="pet-floor-cushion"></div><div class="pet-low-shelf"></div>`;
 if(scene==='meadow')return `${common}<div class="bush" style="left:30%;bottom:118px;width:66px;height:26px"></div><div class="bush" style="right:20%;bottom:120px;width:64px;height:26px"></div>`;
 if(scene==='village')return `${common}<div class="pet-path"></div><div class="pet-house-shape left"></div><div class="pet-house-shape right"></div><div class="pet-lantern-post"></div>`;
 return `${common}<div class="pet-forest-log"></div><div class="bush" style="left:28%;bottom:118px;width:60px;height:22px"></div><div class="bush" style="right:22%;bottom:120px;width:54px;height:22px"></div>`;
}
function petToolButtons(asleep){
 const categoryMeta={food:{emoji:'🍎',label:'喂食'},play:{emoji:'🎲',label:'玩耍'},care:{emoji:'🫧',label:'照顾'},social:{emoji:'💬',label:'社交'}};
 const categories=['food','play','care','social'];
 if(!categories.includes(selectedPetCategory))selectedPetCategory='food';
 const foods=Object.entries(PET_FOODS).map(([k,x])=>`<div class="pet-tool-card"><button class="pet-tool ${selectedPetTool===`food:${k}`?'selected':''}" draggable="${!asleep}" data-pet-tool="food:${k}" title="${x.name}" aria-label="${x.name}" ${asleep?'disabled':''}>${x.emoji}</button><span class="pet-tool-label">${x.name}</span></div>`).join('');
 const plays=Object.entries(PET_PLAYS).map(([k,x])=>`<div class="pet-tool-card"><button class="pet-tool ${selectedPetTool===`play:${k}`?'selected':''}" draggable="${!asleep}" data-pet-tool="play:${k}" title="${x.name}" aria-label="${x.name}" ${asleep?'disabled':''}>${x.emoji}</button><span class="pet-tool-label">${x.name}</span></div>`).join('');
 const care=[['care:bath','🫧','洗澡'],['care:medicine','💊','吃药'],['care:hug','🫂','抱抱'],['care:blanket','🛏️',asleep?'盖被':'小床']].map(([k,e,n])=>`<div class="pet-tool-card"><button class="pet-tool ${selectedPetTool===k?'selected':''}" draggable="${k==='care:blanket'||!asleep}" data-pet-tool="${k}" title="${n}" aria-label="${n}" ${asleep&&k!=='care:blanket'?'disabled':''}>${e}</button><span class="pet-tool-label">${n}</span></div>`).join('');
 const social=[['residents','👥','找居民'],['event','📮','事件'],['family','💞','家庭'],['log','📖','日记'],['decor','🪄','布置']].map(([key,emoji,label])=>`<div class="pet-tool-card"><button class="pet-tool ${petGamePanel===key?'selected':''}" data-pet-panel="${key}" title="${label}" aria-label="${label}">${emoji}</button><span class="pet-tool-label">${label}</span></div>`).join('');
 const strips={food:foods,play:plays,care:care,social:social};
 return `<div class="pet-action-drawer"><div class="pet-action-cats">${categories.map(k=>`<button class="pet-cat-btn ${selectedPetCategory===k?'active':''}" data-pet-category="${k}"><span>${categoryMeta[k].emoji}</span>${categoryMeta[k].label}</button>`).join('')}</div><div class="pet-action-strip">${strips[selectedPetCategory]}</div><div class="pet-action-hint">${petGamePanel==='decor'?'拖动场景里的 emoji 可以改位置，下方还能调大小和前后层级。':'轻点宝宝可以抚摸，也可以点下方项目继续互动。'}</div></div>`;
}
function petResidentOverlay(T,p){return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">💬 居民来往</h3><p class="pet-panel-sub">可以反复聊天，也可以邀请居民一起待在树屋边上挂机一会儿。</p><div class="pet-resident-grid">${T.residents.map(r=>{const talks=(r.talkCountDate===chinaDate()?Number(r.talkCount||0):0),eligible=p?.alive&&petStage(p).key==='adult'&&!p.spouseId&&p.health>=60&&Number(r.friendship||0)>=70;return `<div class="pet-resident-tile"><div class="emoji">${r.emoji}</div><strong>${esc(r.name)}</strong><small>友情 ${Math.round(r.friendship||0)} · 今日互动 ${talks} 次</small><div class="pet-resident-actions"><button class="pet-resident-mini" data-pet-talk="${r.id}">聊天</button><button class="pet-resident-mini alt" data-pet-hang="${r.id}">挂机</button></div>${eligible?`<button class="marry" data-pet-marry="${r.id}" title="求婚">💍</button>`:''}</div>`}).join('')}</div></div>`}
function petEventOverlay(T,p){if(isPetNight())return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">🌙 村庄睡着了</h3><div class="pet-event-mini"><p>白天再来看看今天会发生什么吧。</p></div></div>`;if(!T.event)return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">✅ 今日事件完成</h3><div class="pet-event-mini"><p>${esc(T.lastEventSummary||'今天平静又舒服。')}</p></div></div>`;const e=PET_EVENTS.find(x=>x.id===T.event.templateId)||PET_EVENTS[0],r=T.residents.find(x=>x.id===T.event.residentId)||T.residents[0];return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">${e.icon} ${esc(e.title)}</h3><div class="pet-event-mini"><p>${esc(e.text.replace('{resident}',`${r.emoji}${r.name}`))}</p><div class="pet-event-choices">${e.options.map((o,i)=>`<button data-pet-event-choice="${i}">${esc(o.label)}</button>`).join('')}</div></div></div>`}
function petFamilyOverlay(T,p){const spouse=T.residents.find(r=>r.id===p.spouseId),children=p.children||[];let members='';if(spouse)members+=`<div class="pet-family-chip"><span class="emoji">${spouse.emoji}</span><div><strong>${esc(spouse.name)}</strong><small>伴侣 · ${esc(p.marriedAt)}</small></div></div>`;children.forEach(c=>{const age=Math.max(0,Math.floor((Date.now()-new Date(c.bornAt).getTime())/86400000));members+=`<div class="pet-family-chip"><span class="emoji">${age<2?'🐣':c.emoji}</span><div><strong>${esc(c.name)}</strong><small>${age<2?'小宝宝':`出生第${age+1}天`}</small></div></div>`});let action='';if(spouse){if(p.babyReady)action='<button class="btn primary" data-pet-family="welcome">迎接小宝宝 🐣</button>';else if(p.babyDueDate)action=`<span class="status-pill">🥚 ${esc(p.babyDueDate)}</span>`;else if(!p.nextBabyDate||p.nextBabyDate<=chinaDate())action='<button class="btn soft" data-pet-family="plan">准备宝宝蛋</button>'}else action='<div class="pet-panel-sub">成年、健康达到60、友情达到70后，可以向喜欢的居民求婚。</div>';return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">💞 家庭</h3><div class="pet-family-grid">${members||'<div class="pet-family-chip"><span class="emoji">🏡</span><div><strong>安静的小树屋</strong><small>以后会慢慢热闹起来</small></div></div>'}</div><div style="margin-top:12px">${action}</div></div>`}
function petLogOverlay(p){return `<div class="pet-panel-overlay"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">📖 小日记</h3><div class="pet-log-mini">${(p.log||[]).slice(0,16).map(x=>`<div class="pet-log-mini-row"><span>${x.icon||'🐾'}</span><div>${esc(x.msg)}<small>${new Date(x.at).toLocaleString('zh-CN')}</small></div></div>`).join('')||'<div class="pet-panel-sub">今天还没有发生小故事。</div>'}</div></div>`}
function petDecorOverlay(T,p){ensureDecorState();const scene=T.scene||'forest',coins=Number(T.decorCoins||0),selected=decorSelected(scene),unlocked=new Set(T.decorUnlocked||[]),sceneItems=[...decorSceneList(scene)].sort((a,b)=>b.z-a.z),shop=DECOR_STORE.map(item=>{const have=unlocked.has(item.id);return `<div class="pet-decor-shop-row"><div class="emoji">${item.emoji}</div><div><strong>${esc(item.name)}</strong><small>${have?'已拥有，可重复摆放':`${item.price} 积分`}</small></div><div class="btns">${have?`<button class="primary" data-pet-decor-place="${item.id}">摆进场景</button>`:`<button ${coins<item.price?'disabled':''} data-pet-decor-buy="${item.id}">购买</button>`}</div></div>`}).join('');const selectedBox=selected?`<div class="pet-decor-selected"><div class="pet-decor-selected-head"><span class="big">${selected.emoji}</span><div><strong>${esc(selected.name||'场景摆设')}</strong><div class="pet-decor-help">拖动它可以改位置。当前大小 ${selected.scale.toFixed(2)} 倍，层级 ${Math.round(selected.z)}。</div></div></div><div class="pet-decor-actions"><button data-pet-decor-act="front">前一层</button><button data-pet-decor-act="back">后一层</button><button data-pet-decor-act="bigger">放大</button><button data-pet-decor-act="smaller">缩小</button><button data-pet-decor-act="clone">复制一个</button><button data-pet-decor-act="delete">删除</button><button data-pet-decor-act="clear-select">取消选中</button></div></div>`:`<div class="pet-decor-selected"><div class="pet-decor-help">点场景里的 emoji 就能选中；按住拖动可以挪位置。小游戏获得的积分可以在这里买新摆设。</div></div>`;return `<div class="pet-panel-overlay decor"><button class="pet-panel-close" data-pet-close>✕</button><h3 class="pet-panel-title">🪄 场景布置</h3><div class="pet-decor-balance"><span>当前场景：${PET_SCENES[scene].label}</span><span class="coin">✨ ${coins} 积分</span></div>${selectedBox}<div class="pet-decor-sections"><div class="pet-decor-scene-list"><h4 style="margin:0">本场景摆设</h4>${sceneItems.map(d=>`<button class="pet-decor-scene-row ${selectedPetDecorId===d.id?'active':''}" data-pet-decor-select="${d.id}"><div class="emoji">${d.emoji}</div><div><strong>${esc(d.name||'摆设')}</strong><small>层级 ${Math.round(d.z)} · ${d.scale.toFixed(2)} 倍</small></div><span>选中</span></button>`).join('')||'<div class="pet-decor-help">当前场景还没有摆设。</div>'}</div><div class="pet-decor-shop"><h4 style="margin:0">积分商店</h4>${shop}</div></div></div>`}
function petGameOverlay(T,p){if(petGamePanel==='residents')return petResidentOverlay(T,p);if(petGamePanel==='event')return petEventOverlay(T,p);if(petGamePanel==='family')return petFamilyOverlay(T,p);if(petGamePanel==='log')return petLogOverlay(p);if(petGamePanel==='decor')return petDecorOverlay(T,p);return ''}
function renderPetHome(){const el=$('#homePetSummary');if(!el)return;const p=tamagotchiData().current;if(!p)el.textContent='树屋还空着，领养第一位会长大、交朋友的小居民吧。';else if(!p.alive)el.textContent=`${p.name}已经离开树屋。它的回忆会保留下来，也可以迎接新的小蛋。`;else{const st=petStage(p),need=[p.hunger,p.happiness,p.cleanliness].filter(x=>x<35).length;el.textContent=`${p.emoji}${p.name}是${st.label}，${isPetNight()?'现在正盖着小被子睡觉。':need?`有${need}项需要你照顾。`:'今天状态不错，正在森林里等你。'}`}}
function renderVillage(){const T=tamagotchiData(),p=T.current,scene=T.scene||'forest',phase=petTimePhase(),night=isPetNight();ensureDecorState();$('#petChinaClock').textContent=`中国时间 ${chinaClock()} · ${phase.label}`;if(!p){$('#petMain').innerHTML=`<div class="pet-game-shell"><div class="pet-game-stage scene-${scene} phase-${phase.key} ${night?'night':''}"><div class="pet-scenery">${petSceneDecor(scene,night)}</div>${renderPlacedDecor(scene)}<div class="pet-scene-indicator">${PET_SCENES[scene].label}</div><button class="pet-scene-arrow left" data-pet-scene-prev aria-label="上一个场景">◀</button><button class="pet-scene-arrow right" data-pet-scene-next aria-label="下一个场景">▶</button><div class="pet-coin-chip">✨ ${T.decorCoins||0}</div><div class="pet-empty-stage"><div class="egg">🥚</div><h2>森林里出现了一枚小蛋</h2><p>领养后，可以直接在画面里喂食、玩耍、拜访居民和经历事件。</p><button class="btn primary" data-pet-main="start">抱回树屋</button></div></div></div>`;return}
 Object.assign(p,normalizeTamagotchiPet(p));const dead=!p.alive,st=petStage(p),danger=p.health<40||p.hunger<25||p.happiness<20||p.cleanliness<20;const idleResident=T.idleResidentId?(T.residents||[]).find(x=>x.id===T.idleResidentId):null;$('#petMain').innerHTML=`<div class="pet-game-shell"><div class="pet-game-stage scene-${scene} phase-${phase.key} ${night?'night':''} ${dead?'pet-dead':''}" data-pet-dropzone><div class="pet-scenery">${petSceneDecor(scene,night)}</div>${renderPlacedDecor(scene)}<div class="pet-scene-indicator">${PET_SCENES[scene].label}</div><button class="pet-scene-arrow left" data-pet-scene-prev aria-label="上一个场景">◀</button><button class="pet-scene-arrow right" data-pet-scene-next aria-label="下一个场景">▶</button><div class="pet-hud"><div class="pet-hud-name">${p.emoji}${esc(p.name)} <small>${st.label} · 第${petAgeDays(p)+1}天</small></div><div class="pet-hud-stats">${petStat('饱腹','🍎',p.hunger)}${petStat('心情','🎈',p.happiness)}${petStat('清洁','🫧',p.cleanliness)}${petStat('健康','❤️',p.health)}<span title="亲密度">💕${Math.round(p.affection)}</span></div><div class="pet-phase-row"><span class="pet-time-badge">${phase.emoji}${phase.label}</span><span>🕒${chinaParts().hour}:${chinaParts().minute}</span></div></div><div class="pet-coin-chip">✨ ${T.decorCoins||0}</div>${night&&p.alive?'<div class="pet-bed">🛏️</div><div class="pet-sleep-z">💤</div>':''}<div class="pet-avatar-wrap ${night&&p.alive?'sleeping':''}" data-pet-avatar><div class="pet-shadow"></div><div class="pet-avatar ${night&&p.alive?'sleeping':''}">${dead?'🪦':p.emoji}</div></div>${idleResident&&!dead?`<div class="pet-idle-tag">${idleResident.emoji}${esc(idleResident.name)} 正在陪你挂机</div>`:''}<div class="pet-fx-layer" id="petFxLayer"></div>${dead?`<div class="pet-empty-stage"><div class="egg">🕯️</div><h2>${esc(p.name)}的纪念树屋</h2><p>回忆会留在日记和纪念册里。</p><button class="btn primary" data-pet-main="restart">迎接新的小蛋</button></div>`:`${danger?'<div class="pet-danger-flash">需要照顾啦</div>':''}`}${petGameOverlay(T,p)}</div>${dead?'':petToolButtons(night)}</div>`}
function renderPetCare(){return}
