function petWait(ms){return new Promise(r=>setTimeout(r,ms))}
function petFx(emoji,cls=''){const layer=$('#petFxLayer');if(!layer)return;const el=document.createElement('span');el.className=`pet-fx ${cls}`;el.textContent=emoji;layer.appendChild(el);setTimeout(()=>el.remove(),1800)}
async function petGameAnimate(kind,emoji='✨'){if(petBusy)return false;const wrap=$('[data-pet-avatar]');if(!wrap)return true;petBusy=true;if(kind==='feed'){petFx(emoji,'food');await petWait(500);wrap.classList.add('chew');await petWait(720)}else if(kind==='play'){petFx(emoji,emoji==='⚽'?'ball':'');wrap.classList.add('play');if(emoji==='🎵'){petFx('🎶');setTimeout(()=>petFx('♪'),220)}await petWait(1450)}else if(kind==='bath'){for(let i=0;i<5;i++)setTimeout(()=>petFx('🫧','bubble'),i*140);wrap.classList.add('wash');await petWait(1050)}else if(kind==='medicine'){petFx('💊','food');await petWait(800)}else if(kind==='hug'||kind==='blanket'){petFx(kind==='hug'?'💕':'✨');wrap.classList.add('hug');await petWait(850)}wrap.classList.remove('chew','play','wash','hug');petBusy=false;return true}
async function petPat(){const p=tamagotchiData().current;if(!p?.alive||petBusy)return;if(Date.now()-petLastPat<1200)return;petLastPat=Date.now();const wrap=$('[data-pet-avatar]');if(!wrap)return;petBusy=true;wrap.classList.add('pat');petFx(Math.random()>.5?'💕':'✨');await petWait(950);wrap.classList.remove('pat');p.happiness=clampPet(p.happiness+2);p.affection=clampPet(p.affection+2);petLog(p,'被轻轻摸了摸，高兴地原地跳了起来。','💕');petBusy=false;await persist('抚摸树屋居民',false,false)}
async function petRunTool(tool){if(!tool||petBusy)return;const [type,key]=tool.split(':');if(type==='food')await petFeed(key);else if(type==='play')await petPlay(key);else if(type==='care')await petCare(key);selectedPetTool=''}
function petConversationLines(r,mode='chat'){const scene=PET_SCENES[tamagotchiData().scene||'forest']?.label||'森林',phase=petTimePhase().label;const byResident={"resident-fio":[`菲奥轻轻点头：今天${scene}很安静。`,`菲奥低声说，${phase}的风最适合散步。`,`菲奥看了看你们的小树屋，说今晚会替大家巡一圈。`],"resident-xiaoha":[`小哈开心地摇尾巴：我刚绕着${scene}跑了一大圈！`,`小哈凑过来问，要不要一起去找好吃的？`,`小哈说他在路边发现了一束很漂亮的小花。`],"resident-lili":[`栗栗展示了今天捡到的亮晶晶小石子。`,`栗栗说她最喜欢${scene}里这一片草丛。`,`栗栗问你要不要一起把小宝贝埋起来当秘密。`],"resident-milu":[`米露带来了新烤好的胡萝卜小面包。`,`米露轻声问你今天过得开不开心。`,`米露说${phase}的时候最适合在树下慢慢聊天。`],"resident-achi":[`阿赤说他刚帮村里送完一圈信。`,`阿赤挑了挑眉，说${scene}今天格外热闹。`,`阿赤压低声音，分享了刚听来的趣事。`],"resident-mimi":[`蜜蜜抱着蜂蜜罐慢吞吞地走过来。`,`蜜蜜说她想在树屋里再摆一盏小灯。`,`蜜蜜笑眯眯地夸宝宝今天气色很好。`],"resident-doudou":[`豆豆掏出一颗新拧紧的小螺丝，骄傲地展示给你看。`,`豆豆说他又修好了村口的小路灯。`,`豆豆问树屋里还有没有什么想要加的新家具。`]};
 const commonChat=[`嗨，${r.name}！`,`今天的${scene}看起来真舒服。`,`${phase}的时候一起聊天最放松了。`,`下次再一起玩！`];
 const commonHang=[`${r.name}来陪你啦。`,`你们一起安安静静地待在${scene}。`,`偶尔抬头看看周围的景色，也很幸福。`,`有你在旁边真好。`];
 const pool=[...(byResident[r.id]||[]),...(mode==='hang'?commonHang:commonChat)];
 const start=petHash(`${r.id}-${chinaDate()}-${mode}-${phase}-${scene}`)%Math.max(pool.length,1);
 const len=mode==='hang'?3:4; const lines=[]; for(let i=0;i<len;i++)lines.push(pool[(start+i)%pool.length]); return lines}
async function petVisitAnimation(id,mode='chat'){const T=tamagotchiData(),r=T.residents.find(x=>x.id===id),wrap=$('[data-pet-avatar]'),stage=$('[data-pet-dropzone]');if(!r||!wrap||!stage||petBusy)return false;petBusy=true;petGamePanel='';renderVillage();await petWait(80);const w=$('[data-pet-avatar]'),st=$('[data-pet-dropzone]');w?.classList.add('leave');await petWait(680);w?.classList.remove('leave');w?.classList.add('visit');const visitor=document.createElement('div');visitor.className='pet-visitor';visitor.textContent=r.emoji;st.appendChild(visitor);await petWait(60);visitor.classList.add('in');await petWait(700);const bubbles=petConversationLines(r,mode);for(const line of bubbles){const b=document.createElement('div');b.className='pet-speech';b.textContent=line;st.appendChild(b);await petWait(mode==='hang'?1040:900);b.remove()}if(mode==='hang'){await petWait(1200)}visitor.classList.add('out');w.classList.remove('visit');w.classList.add('leave');await petWait(680);visitor.remove();w.classList.remove('leave');await petWait(420);petBusy=false;return true}
async function petHangout(id){const T=tamagotchiData(),p=T.current,r=T.residents.find(x=>x.id===id);if(!p?.alive||!r)return;if(isPetNight())return toast('居民们已经回家睡觉啦');r.talkCountDate=r.talkCountDate===chinaDate()?r.talkCountDate:chinaDate();r.talkCount=(r.talkCountDate===chinaDate()?Number(r.talkCount||0):0)+1;const ok=await petVisitAnimation(id,'hang');if(!ok)return;T.idleResidentId=r.id;p.happiness=clampPet(p.happiness+6);p.affection=clampPet(p.affection+3);r.friendship=clampPet(Number(r.friendship||0)+(r.talkCount>1?2:5));petLog(p,`和${r.emoji}${r.name}在${PET_SCENES[T.scene||'forest'].label}里一起待了一会儿。`,'🌿');await persist(`与居民挂机：${r.name}`,true,true)}
async function petFeed(kind){const p=tamagotchiData().current,x=PET_FOODS[kind];if(!p?.alive||!x)return;if(isPetNight())return toast(`${p.name}已经睡着啦`);if(p.hunger>95&&kind!=='cake')return toast(`${p.name}已经吃得饱饱的`);await petGameAnimate('feed',x.emoji);p.hunger=clampPet(p.hunger+x.hunger);p.happiness=clampPet(p.happiness+x.happiness);p.health=clampPet(p.health+x.health);p.cleanliness=clampPet(p.cleanliness+x.cleanliness);p.affection=clampPet(p.affection+1);p.daily.fed=true;petLog(p,`吃了${x.emoji}${x.name}，肚子暖暖的。`,x.emoji);await persist(`喂树屋居民：${x.name}`,true,true)}
async function petPlay(kind){const p=tamagotchiData().current,x=PET_PLAYS[kind];if(!p?.alive||!x)return;if(isPetNight())return toast(`${p.name}正在睡觉`);await petGameAnimate('play',x.emoji);const bonus=Math.floor(Math.random()*5);p.happiness=clampPet(p.happiness+x.happiness+bonus);p.hunger=clampPet(p.hunger+x.hunger);p.cleanliness=clampPet(p.cleanliness+x.cleanliness);p.affection=clampPet(p.affection+3);p.daily.played=true;petLog(p,`和你玩了${x.emoji}${x.name}，开心得转了好几圈。`,x.emoji);await persist(`陪树屋居民玩：${x.name}`,true,true)}
async function petCare(action){const p=tamagotchiData().current;if(!p?.alive)return;if(isPetNight()&&action!=='blanket')return toast(`${p.name}已经睡着啦`);await petGameAnimate(action,action==='bath'?'🫧':action==='medicine'?'💊':action==='hug'?'💕':'✨');if(action==='bath'){p.cleanliness=clampPet(p.cleanliness+38);p.happiness=clampPet(p.happiness-2);p.daily.cleaned=true;petLog(p,'洗完澡变得香香软软。','🫧')}if(action==='medicine'){if(p.health>94)return toast(`${p.name}现在很健康`);p.health=clampPet(p.health+22);p.happiness=clampPet(p.happiness-2);petLog(p,'认真接受了健康照顾。','💊')}if(action==='hug'){p.happiness=clampPet(p.happiness+7);p.affection=clampPet(p.affection+5);petLog(p,'被你抱在怀里轻轻蹭了蹭。','🫂')}if(action==='blanket'){p.happiness=clampPet(p.happiness+3);p.affection=clampPet(p.affection+2);petLog(p,isPetNight()?'你替它把小被角盖好了。':'你们一起把小床整理得蓬蓬松松。','🛏️')}await persist(`照顾树屋居民：${action}`,true,true)}
async function petTalk(id){const T=tamagotchiData(),p=T.current,r=T.residents.find(x=>x.id===id);if(!p?.alive||!r)return;if(isPetNight())return toast('居民们已经回家睡觉啦');r.talkCountDate=r.talkCountDate===chinaDate()?r.talkCountDate:chinaDate();r.talkCount=(r.talkCountDate===chinaDate()?Number(r.talkCount||0):0)+1;r.lastTalkDate=chinaDate();const ok=await petVisitAnimation(id,'chat');if(!ok)return;T.idleResidentId='';const bonus=r.talkCount>1?2:5;r.friendship=clampPet(Number(r.friendship||0)+bonus);p.happiness=clampPet(p.happiness+(r.talkCount>1?2:4));p.affection=clampPet(p.affection+1);const logs=[`和${r.emoji}${r.name}在${PET_SCENES[T.scene||'forest'].label}里聊了很久。`,`听${r.emoji}${r.name}分享了不少只属于${petTimePhase().label}的故事。`,`你们在树屋边上把刚看到的小景色来来回回说了好几遍。`,`这次聊天让${r.name}看起来更亲近你了。`];petLog(p,logs[petHash(`${id}-${chinaDate()}-${r.talkCount}-${T.scene}`)%logs.length],'💬');await persist(`与居民聊天：${r.name}`,true,true)}
async function resolvePetEvent(index){const T=tamagotchiData(),p=T.current,ev=T.event;if(!p?.alive||!ev)return;const tpl=PET_EVENTS.find(x=>x.id===ev.templateId),op=tpl?.options?.[Number(index)],r=T.residents.find(x=>x.id===ev.residentId);if(!op||!r)return;await petGameAnimate('play',tpl.icon);for(const [k,v] of Object.entries(op.effects||{}))p[k]=clampPet(Number(p[k]||0)+v);r.friendship=clampPet(Number(r.friendship||0)+Number(op.friendship||0));p.affection=clampPet(p.affection+2);T.lastEventDate=chinaDate();T.lastEventSummary=`${tpl.icon}${tpl.title}：${op.log}。`;T.event=null;petLog(p,`${op.log}，和${r.emoji}${r.name}的友情更深了。`,tpl.icon);await persist(`完成树屋事件：${tpl.title}`,true,true)}
async function marryPetResident(id){const T=tamagotchiData(),p=T.current,r=T.residents.find(x=>x.id===id);if(!p?.alive||!r)return;if(petStage(p).key!=='adult'||p.health<60||r.friendship<70||p.spouseId)return toast('现在还没有满足结婚条件');if(!confirm(`让${p.emoji}${p.name}和${r.emoji}${r.name}结婚，一起住进树屋吗？`))return;p.spouseId=r.id;p.marriedAt=chinaDate();p.babyDueDate=addDateDays(chinaDate(),3);p.babyReady=false;p.happiness=clampPet(p.happiness+20);p.affection=clampPet(p.affection+10);petLog(p,`和${r.emoji}${r.name}举行了小小的树屋婚礼。`,'💍');await persist(`树屋居民结婚：${p.name}与${r.name}`,true,true)}
async function petFamilyAction(action){const T=tamagotchiData(),p=T.current;if(!p?.alive||!p.spouseId)return;if(action==='plan'){p.babyDueDate=addDateDays(chinaDate(),3);p.babyReady=false;petLog(p,'树屋里准备好了一张柔软的宝宝小床。','🥚')}if(action==='welcome'&&p.babyReady){const spouse=T.residents.find(r=>r.id===p.spouseId),names=['小芽','团子','星星','糯米','豆包','小叶'],name=names[petHash(`${p.id}-${Date.now()}`)%names.length],emoji=(petHash(name)%2?p.emoji:(spouse?.emoji||p.emoji));p.children.push({id:uid('baby'),name,emoji,bornAt:nowISO()});p.babyReady=false;p.babyDueDate='';p.nextBabyDate=addDateDays(chinaDate(),7);p.happiness=clampPet(p.happiness+20);petLog(p,`小宝宝🐣${name}出生了，树屋一下子热闹起来。`,'🐣')}await persist(action==='welcome'?'迎接树屋宝宝':'准备树屋宝宝',true,true)}
function setPetSetupEmoji(emoji){$('#petSetupEmoji').value=emoji;$$('#petEmojiPicker [data-pet-emoji]').forEach(b=>b.classList.toggle('active',b.dataset.petEmoji===emoji))}
function openPetSetup(){if(tamagotchiData().current?.alive)return toast('树屋里已经住着一位小居民啦');$('#petSetupForm').reset();$('#petSetupName').value='';setPetSetupEmoji('🐿️');$('#petSetupDialog').showModal()}
async function createTamagotchiPet(){const T=tamagotchiData(),name=$('#petSetupName').value.trim(),emoji=$('#petSetupEmoji').value||'🐿️';if(!name)return toast('先给小居民起一个名字');const p=normalizeTamagotchiPet({id:uid('pet'),name,emoji,bornAt:nowISO(),hunger:86,happiness:84,cleanliness:90,health:100,affection:25,lastUpdated:nowISO(),daily:{date:chinaDate(),fed:false,played:false,cleaned:false},children:[],log:[]});petLog(p,`${emoji}${name}从小蛋里探出了脑袋，正式住进树屋。`,'🥚');T.current=p;T.event=null;T.lastEventDate='';T.lastEventSummary='';$('#petSetupDialog').close();await persist(`领养树屋居民：${name}`,true,true)}

async function renderBackup(){const snaps=(await idbAll('snapshots')).sort((a,b)=>String(b.at).localeCompare(String(a.at)));let persisted=false;try{persisted=await navigator.storage?.persisted?.()}catch{};const external=state.settings.lastExternalBackupAt?new Date(state.settings.lastExternalBackupAt).toLocaleString('zh-CN'):'从未';$('#backupCards').innerHTML=[['主数据库','IndexedDB','浏览器内主要数据仓'],['本地镜像','已同步','localStorage 副本'],['版本快照',`${snaps.length}份`,'保留最近50次修改'],['外部备份',external,persisted?'浏览器存储已获持久权限':'仍建议保留下载的JSON']].map((x,i)=>`<div class="backup-card"><div class="label">${x[0]}</div><strong class="${i===3&&!state.settings.lastExternalBackupAt?'warn':'safe'}">${x[1]}</strong><p>${x[2]}</p></div>`).join('');$('#dailyBackupSwitch').classList.toggle('on',!!state.settings.autoDailyDownload);$('#everyChangeSwitch').classList.toggle('on',!!state.settings.everyChangeDownload);$('#snapshotList').innerHTML=snaps.slice(0,12).map(s=>`<div class="snapshot"><div><strong>${new Date(s.at).toLocaleString('zh-CN')}</strong><br><small>${esc(s.reason)}</small></div><button class="btn ghost" data-restore-snapshot="${s.id}">恢复</button></div>`).join('')||'<div class="empty">还没有版本快照。</div>';$('#diagnostics').innerHTML=`应用版本：1.9.4（积分布置与树屋修正）<br>数据结构版本：${state.schemaVersion}<br>账目：${state.ledger.records.length}笔<br>家务：${state.chores.items.length}项<br>日历记录：${Object.keys(state.modules.calendar.entries||{}).length}天<br>餐厅与外卖：${restaurantData().items.length}次<br>树屋居民：${tamagotchiData().current?.name||'尚未领养'}<br>愿望：${state.modules.wishlist.items.length}件<br>数独完成：${state.modules.brain.sudoku.stats.completed||0}题<br>空当接龙胜利：${state.modules.brain.freecell.stats.won||0}局<br>扫雷胜利：${state.modules.brain.minesweeper.stats.won||0}局<br>当前来源：${location.protocol}<br>最近更新：${new Date(state.updatedAt).toLocaleString('zh-CN')}`;$('#backupBadge').textContent=state.settings.lastExternalBackupAt?`外部备份：${new Date(state.settings.lastExternalBackupAt).toLocaleDateString('zh-CN')}`:'外部备份尚未建立'}

const SUDOKU_LEVELS={easy:{label:'简单',clues:42},medium:{label:'中等',clues:34},hard:{label:'困难',clues:28}};
let sudokuSelected=-1,sudokuChecked=false,sudokuTimer=null;
function sudokuData(){return state.modules.brain.sudoku}
function shuffle(a){const b=[...a];for(let i=b.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function sudokuSolution(){const pattern=(r,c)=>(r*3+Math.floor(r/3)+c)%9;const groups=shuffle([0,1,2]);const rows=groups.flatMap(g=>shuffle([0,1,2]).map(x=>g*3+x));const stacks=shuffle([0,1,2]);const cols=stacks.flatMap(g=>shuffle([0,1,2]).map(x=>g*3+x));const nums=shuffle([1,2,3,4,5,6,7,8,9]);return rows.flatMap(r=>cols.map(c=>nums[pattern(r,c)]))}
function sudokuCandidates(board,idx){if(board[idx])return[];const row=Math.floor(idx/9),col=idx%9,used=new Set();for(let i=0;i<9;i++){used.add(board[row*9+i]);used.add(board[i*9+col])}const br=Math.floor(row/3)*3,bc=Math.floor(col/3)*3;for(let r=br;r<br+3;r++)for(let c=bc;c<bc+3;c++)used.add(board[r*9+c]);return [1,2,3,4,5,6,7,8,9].filter(n=>!used.has(n))}
function countSudokuSolutions(board,limit=2){let best=-1,bestC=null;for(let i=0;i<81;i++)if(!board[i]){const c=sudokuCandidates(board,i);if(!c.length)return 0;if(bestC===null||c.length<bestC.length){best=i;bestC=c;if(c.length===1)break}}if(best===-1)return 1;let count=0;for(const n of bestC){board[best]=n;count+=countSudokuSolutions(board,limit-count);board[best]=0;if(count>=limit)return count}return count}
function makeSudokuPuzzle(solution,clues){const puzzle=[...solution];for(const idx of shuffle([...Array(81).keys()])){if(puzzle.filter(Boolean).length<=clues)break;const old=puzzle[idx];puzzle[idx]=0;if(countSudokuSolutions([...puzzle],2)!==1)puzzle[idx]=old}return puzzle}
function sudokuElapsed(cur=sudokuData().current){if(!cur)return 0;let s=Number(cur.elapsedSeconds||0);if(cur.status==='playing'&&!cur.paused&&cur.runningSince)s+=Math.max(0,Math.floor((Date.now()-new Date(cur.runningSince).getTime())/1000));return s}
function formatTime(sec){sec=Math.max(0,Math.floor(Number(sec)||0));return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function captureSudokuTime(cur=sudokuData().current){if(cur&&cur.status==='playing'&&!cur.paused&&cur.runningSince){cur.elapsedSeconds=sudokuElapsed(cur);cur.runningSince=nowISO()}}
async function saveSudokuProgress(reason='数独进度'){captureSudokuTime();await persist(reason,false,false)}
async function newSudoku(){const S=sudokuData(),old=S.current;if(old&&old.status==='playing'&&old.entries?.some((v,i)=>!old.puzzle[i]&&v)&&!confirm('当前题目还没完成，确定换一题吗？'))return;const difficulty=$('#sudokuDifficulty').value||'medium',solution=sudokuSolution(),puzzle=makeSudokuPuzzle(solution,SUDOKU_LEVELS[difficulty].clues);S.stats.played=Number(S.stats.played||0)+1;S.current={id:uid('sudoku'),difficulty,puzzle,solution,entries:[...puzzle],status:'playing',createdAt:nowISO(),completedAt:'',elapsedSeconds:0,runningSince:nowISO(),paused:false,hints:0};sudokuSelected=-1;sudokuChecked=false;await persist('开始数独',true,true);startSudokuClock()}
function completeSudoku(){const S=sudokuData(),cur=S.current;if(!cur||cur.status==='completed')return;captureSudokuTime(cur);cur.status='completed';cur.paused=true;cur.runningSince=null;cur.completedAt=nowISO();S.stats.completed=Number(S.stats.completed||0)+1;const sec=Number(cur.elapsedSeconds||0);if(S.stats.bestSeconds==null||sec<S.stats.bestSeconds)S.stats.bestSeconds=sec;S.history.unshift({id:cur.id,date:today(),completedAt:cur.completedAt,difficulty:cur.difficulty,seconds:sec,hints:cur.hints||0});S.history=S.history.slice(0,20);const reward={easy:12,medium:16,hard:22}[cur.difficulty]||15;awardDecorCoins(reward,'数独完成');persist('完成数独',true,true);toast(`完成啦！用时 ${formatTime(sec)}`)}
function setSudokuNumber(n){const cur=sudokuData().current;if(!cur||cur.status!=='playing'||cur.paused||sudokuSelected<0||cur.puzzle[sudokuSelected])return;captureSudokuTime(cur);cur.entries[sudokuSelected]=n;sudokuChecked=false;persist('填写数独',false,false);if(cur.entries.every((v,i)=>v===cur.solution[i]))completeSudoku()}
function sudokuRelated(a,b){const ar=Math.floor(a/9),ac=a%9,br=Math.floor(b/9),bc=b%9;return ar===br||ac===bc||(Math.floor(ar/3)===Math.floor(br/3)&&Math.floor(ac/3)===Math.floor(bc/3))}
function renderSudoku(){const S=sudokuData(),cur=S.current,stats=S.stats||{};const best=stats.bestSeconds==null?'—':formatTime(stats.bestSeconds);$('#sudokuStatus').innerHTML=[['已开题',stats.played||0],['已完成',stats.completed||0],['最佳用时',best],['当前用时',cur?formatTime(sudokuElapsed(cur)):'00:00']].map(x=>`<div class="sudoku-stat"><div class="label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');$('#sudokuNumberPad').innerHTML=[1,2,3,4,5,6,7,8,9,0].map(n=>`<button class="number-key ${n===0?'erase':''}" data-sudoku-number="${n}">${n||'清除'}</button>`).join('');if(!cur){$('#sudokuGrid').innerHTML='';$('#sudokuMessage').textContent='点“新题目”开始。先从确定性最高的空格排除候选数字。';$('#pauseSudokuBtn').textContent='暂停'}else{const selectedValue=sudokuSelected>=0?cur.entries[sudokuSelected]:0;$('#sudokuGrid').innerHTML=cur.entries.map((v,i)=>{const r=Math.floor(i/9),c=i%9,classes=['sudoku-cell'];if(cur.puzzle[i])classes.push('given');if(c===2||c===5)classes.push('box-right');if(r===2||r===5)classes.push('box-bottom');if(sudokuSelected===i)classes.push('selected');else if(sudokuSelected>=0&&sudokuRelated(sudokuSelected,i))classes.push('related');if(selectedValue&&v===selectedValue&&i!==sudokuSelected)classes.push('same');if(sudokuChecked&&v&&!cur.puzzle[i]&&v!==cur.solution[i])classes.push('wrong');return `<button class="${classes.join(' ')}" data-sudoku-cell="${i}" role="gridcell" aria-label="第${r+1}行第${c+1}列${v?`数字${v}`:'空格'}">${v||''}</button>`}).join('');const filled=cur.entries.filter(Boolean).length,wrong=cur.entries.filter((v,i)=>v&&v!==cur.solution[i]).length;$('#sudokuDifficulty').value=cur.difficulty;$('#pauseSudokuBtn').textContent=cur.paused?'继续':'暂停';$('#sudokuMessage').textContent=cur.status==='completed'?`完成！${SUDOKU_LEVELS[cur.difficulty].label}题，用时 ${formatTime(cur.elapsedSeconds)}，使用 ${cur.hints||0} 次提示。`:cur.paused?'题目已暂停，点“继续”恢复计时。':sudokuChecked?(wrong?`目前有 ${wrong} 格不正确，红色格需要重新推理。`:'当前已填写的数字都正确。'):`已填 ${filled}/81 格｜提示 ${cur.hints||0} 次`}
$('#sudokuHistory').innerHTML=(S.history||[]).map(h=>`<div class="sudoku-history-row"><div><strong>${SUDOKU_LEVELS[h.difficulty]?.label||h.difficulty}数独</strong><br><small>${esc(h.date)} · 提示 ${h.hints||0} 次</small></div><strong>${formatTime(h.seconds)}</strong></div>`).join('')||'<div class="empty">完成第一题后，记录会出现在这里。</div>'}
function startSudokuClock(){clearInterval(sudokuTimer);sudokuTimer=setInterval(()=>{if(currentView==='brain'&&sudokuData().current?.status==='playing'&&!sudokuData().current?.paused){const boxes=$$('#sudokuStatus .sudoku-stat strong');if(boxes[3])boxes[3].textContent=formatTime(sudokuElapsed())}},1000)}


function brainGame(){return state.modules.brain.activeGame||'sudoku'}
function renderBrainTabs(){const game=brainGame();$$('[data-brain-game]').forEach(b=>b.classList.toggle('active',b.dataset.brainGame===game));$$('.brain-game').forEach(x=>x.classList.toggle('active',x.id===`brain-game-${game}`))}
async function setBrainGame(game){if(!['sudoku','freecell','minesweeper'].includes(game))return;state.modules.brain.activeGame=game;await persist('切换脑力游戏',false,false)}

const FC_SUITS=[{key:'S',symbol:'♠',red:false},{key:'H',symbol:'♥',red:true},{key:'D',symbol:'♦',red:true},{key:'C',symbol:'♣',red:false}];
let freecellSelected=null,freecellTimer=null;
function freecellData(){return state.modules.brain.freecell}
function fcRank(r){return ({1:'A',11:'J',12:'Q',13:'K'})[r]||String(r)}
function fcSuit(s){return FC_SUITS.find(x=>x.key===s)}
function fcColor(card){return fcSuit(card.suit).red?'red':'black'}
function fcElapsed(cur=freecellData().current){if(!cur)return 0;let s=Number(cur.elapsedSeconds||0);if(cur.status==='playing'&&cur.runningSince)s+=Math.max(0,Math.floor((Date.now()-new Date(cur.runningSince).getTime())/1000));return s}
function captureFreecellTime(cur=freecellData().current){if(cur&&cur.status==='playing'&&cur.runningSince){cur.elapsedSeconds=fcElapsed(cur);cur.runningSince=nowISO()}}
function fcStateSnapshot(cur){return {columns:clone(cur.columns),freecells:clone(cur.freecells),foundations:clone(cur.foundations),moves:cur.moves,status:cur.status,elapsedSeconds:fcElapsed(cur)}}
function fcRestoreSnapshot(cur,s){cur.columns=clone(s.columns);cur.freecells=clone(s.freecells);cur.foundations=clone(s.foundations);cur.moves=Number(s.moves||0);cur.status=s.status||'playing';cur.elapsedSeconds=Number(s.elapsedSeconds||0);cur.runningSince=cur.status==='playing'?nowISO():null}
function fcPushUndo(cur){cur.undo=cur.undo||[];cur.undo.push(fcStateSnapshot(cur));cur.undo=cur.undo.slice(-60)}
function fcSequence(cards,start){if(start<0||start>=cards.length)return null;const seq=cards.slice(start);for(let i=0;i<seq.length-1;i++)if(seq[i].rank!==seq[i+1].rank+1||fcColor(seq[i])===fcColor(seq[i+1]))return null;return seq}
function fcSelectedCards(cur,sel=freecellSelected){if(!sel)return null;if(sel.zone==='free'){const card=cur.freecells[sel.index];return card?[card]:null}return fcSequence(cur.columns[sel.column],sel.index)}
function fcRemoveSelected(cur,sel,count){if(sel.zone==='free')cur.freecells[sel.index]=null;else cur.columns[sel.column].splice(sel.index,count)}
function fcMoveCapacity(cur,destColumn){const free=cur.freecells.filter(x=>!x).length;let empty=cur.columns.filter(x=>!x.length).length;if(!cur.columns[destColumn].length)empty=Math.max(0,empty-1);return (free+1)*(2**empty)}
function fcCanPlace(card,target){return !target||(target.rank===card.rank+1&&fcColor(target)!==fcColor(card))}
function fcSafeForAuto(cur,card){if(card.rank<=2)return true;const color=fcColor(card),opposite=FC_SUITS.filter(s=>(s.red?'red':'black')!==color),sameOther=FC_SUITS.find(s=>s.key!==card.suit&&(s.red?'red':'black')===color);return opposite.every(s=>Number(cur.foundations[s.key]||0)>=card.rank-1)&&Number(cur.foundations[sameOther.key]||0)>=card.rank-2}
function fcCollectAvailable(cur,safeOnly=true){let moved=0,again=true;while(again){again=false;for(let i=0;i<4;i++){const c=cur.freecells[i];if(c&&c.rank===Number(cur.foundations[c.suit]||0)+1&&(!safeOnly||fcSafeForAuto(cur,c))){cur.freecells[i]=null;cur.foundations[c.suit]=c.rank;moved++;again=true}}for(let i=0;i<8;i++){const col=cur.columns[i],c=col[col.length-1];if(c&&c.rank===Number(cur.foundations[c.suit]||0)+1&&(!safeOnly||fcSafeForAuto(cur,c))){col.pop();cur.foundations[c.suit]=c.rank;moved++;again=true}}}return moved}
function fcWon(cur){return FC_SUITS.every(s=>Number(cur.foundations[s.key]||0)===13)}
function fcFinish(cur){const F=freecellData(),stats=F.stats;captureFreecellTime(cur);cur.status='won';cur.runningSince=null;cur.completedAt=nowISO();stats.won=Number(stats.won||0)+1;stats.bestMoves=stats.bestMoves==null?cur.moves:Math.min(stats.bestMoves,cur.moves);stats.bestSeconds=stats.bestSeconds==null?cur.elapsedSeconds:Math.min(stats.bestSeconds,cur.elapsedSeconds);F.history.unshift({id:cur.id,date:today(),seconds:cur.elapsedSeconds,moves:cur.moves});F.history=F.history.slice(0,20);awardDecorCoins(20,'空当接龙胜利');toast(`空当接龙完成！${cur.moves}步`)}
async function newFreecell(){const F=freecellData(),old=F.current;if(old&&old.status==='playing'&&old.moves>0&&!confirm('当前牌局还没完成，确定换一局吗？'))return;const deck=[];for(const s of FC_SUITS)for(let r=1;r<=13;r++)deck.push({id:`${s.key}${r}-${Math.random().toString(16).slice(2)}`,suit:s.key,rank:r});const shuffled=shuffle(deck),columns=Array.from({length:8},()=>[]);shuffled.forEach((c,i)=>columns[i%8].push(c));F.stats.played=Number(F.stats.played||0)+1;F.current={id:uid('freecell'),columns,freecells:[null,null,null,null],foundations:{S:0,H:0,D:0,C:0},moves:0,status:'playing',createdAt:nowISO(),completedAt:'',elapsedSeconds:0,runningSince:nowISO(),undo:[],initial:null};F.current.initial=fcStateSnapshot(F.current);freecellSelected=null;await persist('开始空当接龙',true,true);startFreecellClock()}
function selectFreecellSource(sel){const cur=freecellData().current;if(!cur||cur.status!=='playing')return;const cards=fcSelectedCards(cur,sel);if(!cards)return toast('这组牌不是红黑交替、数字递减的连续序列');freecellSelected=sel;renderFreecell()}
async function moveFreecellTo(dest){const cur=freecellData().current;if(!cur||cur.status!=='playing'||!freecellSelected)return;const moving=fcSelectedCards(cur);if(!moving)return;let valid=false;
 if(dest.zone==='free')valid=moving.length===1&&!cur.freecells[dest.index];
 if(dest.zone==='foundation')valid=moving.length===1&&moving[0].suit===dest.suit&&moving[0].rank===Number(cur.foundations[dest.suit]||0)+1;
 if(dest.zone==='tableau'&&!(freecellSelected.zone==='tableau'&&freecellSelected.column===dest.column)){const col=cur.columns[dest.column],target=col[col.length-1];valid=moving.length<=fcMoveCapacity(cur,dest.column)&&fcCanPlace(moving[0],target)}
 if(!valid)return toast('这张牌暂时不能放到那里');
 captureFreecellTime(cur);fcPushUndo(cur);fcRemoveSelected(cur,freecellSelected,moving.length);
 if(dest.zone==='free')cur.freecells[dest.index]=moving[0];
 if(dest.zone==='foundation')cur.foundations[dest.suit]=moving[0].rank;
 if(dest.zone==='tableau')cur.columns[dest.column].push(...moving);
 cur.moves=Number(cur.moves||0)+1;const autoMoved=freecellData().autoCollect!==false?fcCollectAvailable(cur,true):0;cur.moves+=autoMoved;freecellSelected=null;const won=fcWon(cur);if(won)fcFinish(cur);await persist(won?'完成空当接龙':'空当接龙移动',won,won);if(autoMoved&&!won)toast(`自动收进 ${autoMoved} 张安全牌`)}
async function undoFreecell(){const cur=freecellData().current;if(!cur||!cur.undo?.length)return toast('没有可以撤销的步骤');captureFreecellTime(cur);const s=cur.undo.pop();fcRestoreSnapshot(cur,s);freecellSelected=null;await persist('撤销空当接龙',false,false)}
async function autoFreecell(){const F=freecellData(),cur=F.current;F.autoCollect=F.autoCollect===false;if(F.autoCollect&&cur?.status==='playing'){captureFreecellTime(cur);fcPushUndo(cur);const moved=fcCollectAvailable(cur,true);if(moved){cur.moves+=moved;const won=fcWon(cur);if(won)fcFinish(cur);await persist(won?'完成空当接龙':'开启自动收牌',won,won);if(!won)toast(`自动收牌已开启，并收进 ${moved} 张安全牌`);return}cur.undo.pop()}await persist(F.autoCollect?'开启自动收牌':'关闭自动收牌',false,false);toast(`自动收牌已${F.autoCollect?'开启':'关闭'}`)}
async function resetFreecell(){const cur=freecellData().current;if(!cur)return;if(!confirm('把当前牌局恢复到刚发牌时吗？'))return;fcRestoreSnapshot(cur,cur.initial);cur.undo=[];cur.elapsedSeconds=0;cur.runningSince=nowISO();freecellSelected=null;await persist('重置空当接龙',false,false)}
function renderFreecell(){const F=freecellData(),cur=F.current,stats=F.stats||{};$('#autoFreecellBtn').textContent=`自动收牌：${F.autoCollect===false?'关':'开'}`;$('#autoFreecellBtn').classList.toggle('flag-active',F.autoCollect!==false);$('#freecellStatus').innerHTML=[['已开局',stats.played||0],['已胜利',stats.won||0],['最佳步数',stats.bestMoves??'—'],['当前用时',cur?formatTime(fcElapsed(cur)):'00:00']].map(x=>`<div class="game-stat"><div class="label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');
 const top=[];for(let i=0;i<4;i++){const c=cur?.freecells?.[i];top.push(`<button class="fc-slot ${freecellSelected?.zone==='free'&&freecellSelected.index===i?'selected':''}" data-fc-free="${i}">${c?`<span class="${fcColor(c)}"><b>${fcRank(c.rank)}</b><br>${fcSuit(c.suit).symbol}</span>`:'空'}</button>`)}for(const s of FC_SUITS){const rank=cur?.foundations?.[s.key]||0;top.push(`<button class="fc-slot foundation" data-fc-foundation="${s.key}"><span class="${s.red?'red':'black'}">${s.symbol}<br><b>${rank?fcRank(rank):'A→K'}</b></span></button>`)}$('#freecellTop').innerHTML=top.join('');
 if(!cur){$('#freecellColumns').innerHTML=Array.from({length:8},()=>'<div class="fc-column"><div class="fc-empty">牌列</div></div>').join('');$('#freecellMessage').textContent='点“新牌局”开始。红黑交替、数字递减地整理牌列。'}else{const step=Math.max(22,Math.min(31,window.innerWidth/14));$('#freecellColumns').innerHTML=cur.columns.map((col,ci)=>`<div class="fc-column" data-fc-column="${ci}" style="height:${Math.max(280,(col.length-1)*step+78)}px">${col.length?col.map((c,i)=>`<button class="fc-card ${fcColor(c)} ${freecellSelected?.zone==='tableau'&&freecellSelected.column===ci&&i>=freecellSelected.index?'selected':''}" data-fc-card="1" data-fc-column="${ci}" data-fc-index="${i}" style="top:${i*step}px;z-index:${i+1}"><span class="fc-rank">${fcRank(c.rank)}</span><span class="fc-suit">${fcSuit(c.suit).symbol}</span></button>`).join(''):'<div class="fc-empty">空列</div>'}</div>`).join('');$('#freecellMessage').textContent=cur.status==='won'?`完成！用时 ${formatTime(cur.elapsedSeconds)}，共 ${cur.moves} 步。`:freecellSelected?'已选中牌组，请点击自由格、收集区或目标牌列。':`已走 ${cur.moves} 步｜自动收牌${F.autoCollect===false?'已关闭':'已开启'}。点击一张牌或连续牌组，再点击目标位置。`}
 $('#freecellHistory').innerHTML=(F.history||[]).map(h=>`<div class="game-history-row"><div><strong>胜利牌局</strong><br><small>${esc(h.date)} · ${h.moves}步</small></div><strong>${formatTime(h.seconds)}</strong></div>`).join('')||'<div class="empty">完成第一局后，记录会出现在这里。</div>'}
function startFreecellClock(){clearInterval(freecellTimer);freecellTimer=setInterval(()=>{if(currentView==='brain'&&brainGame()==='freecell'&&freecellData().current?.status==='playing'){const boxes=$$('#freecellStatus .game-stat strong');if(boxes[3])boxes[3].textContent=formatTime(fcElapsed())}},1000)}

const MINE_LEVELS={easy:{label:'简单',rows:9,cols:9,mines:10},medium:{label:'中等',rows:12,cols:12,mines:20},hard:{label:'困难',rows:16,cols:16,mines:40}};
let mineFlagMode=false,mineTimer=null;
function mineData(){return state.modules.brain.minesweeper}
function mineElapsed(cur=mineData().current){if(!cur)return 0;let s=Number(cur.elapsedSeconds||0);if(cur.status==='playing'&&cur.runningSince)s+=Math.max(0,Math.floor((Date.now()-new Date(cur.runningSince).getTime())/1000));return s}
function captureMineTime(cur=mineData().current){if(cur&&cur.status==='playing'&&cur.runningSince){cur.elapsedSeconds=mineElapsed(cur);cur.runningSince=nowISO()}}
function mineNeighbors(cur,index){const r=Math.floor(index/cur.cols),c=index%cur.cols,out=[];for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){if(!dr&&!dc)continue;const nr=r+dr,nc=c+dc;if(nr>=0&&nr<cur.rows&&nc>=0&&nc<cur.cols)out.push(nr*cur.cols+nc)}return out}
function mineConfig(difficulty){return MINE_LEVELS[difficulty]||MINE_LEVELS.medium}
function mineCountLimit(difficulty){const cfg=mineConfig(difficulty);return Math.max(1,cfg.rows*cfg.cols-1)}
function normalizedMineCount(difficulty,value){const cfg=mineConfig(difficulty),n=Math.round(Number(value));return Math.min(mineCountLimit(difficulty),Math.max(1,Number.isFinite(n)?n:cfg.mines))}
function mineBestKey(cur){return cur?`${cur.rows}x${cur.cols}-${cur.mines}`:'medium'}
function syncMineCountInput(usePreset=false){const difficulty=$('#mineDifficulty').value||'medium',cfg=mineConfig(difficulty),input=$('#mineCount');input.min=1;input.max=mineCountLimit(difficulty);if(usePreset||!input.value)input.value=cfg.mines;else input.value=normalizedMineCount(difficulty,input.value)}
function createMineCurrent(difficulty,increment=true,minesOverride=null){const M=mineData(),cfg=mineConfig(difficulty),mines=normalizedMineCount(difficulty,minesOverride??cfg.mines);if(increment)M.stats.played=Number(M.stats.played||0)+1;M.current={id:uid('mine'),difficulty,rows:cfg.rows,cols:cfg.cols,mines,board:Array.from({length:cfg.rows*cfg.cols},()=>({mine:false,adj:0,revealed:false,flagged:false})),generated:false,status:'ready',createdAt:nowISO(),completedAt:'',elapsedSeconds:0,runningSince:null,moves:0};mineFlagMode=false}
async function newMine(){const M=mineData(),old=M.current;if(old&&['ready','playing'].includes(old.status)&&old.moves>0&&!confirm('当前雷区还没完成，确定换一局吗？'))return;const difficulty=$('#mineDifficulty').value||'medium',mines=normalizedMineCount(difficulty,$('#mineCount').value);$('#mineCount').value=mines;createMineCurrent(difficulty,true,mines);await persist('开始扫雷',true,true);startMineClock()}
function generateMines(cur,safe){const excluded=new Set([safe,...mineNeighbors(cur,safe)]);let choices=[...Array(cur.board.length).keys()].filter(i=>!excluded.has(i));if(choices.length<cur.mines)choices=[...Array(cur.board.length).keys()].filter(i=>i!==safe);for(const i of shuffle(choices).slice(0,cur.mines))cur.board[i].mine=true;cur.board.forEach((cell,i)=>cell.adj=mineNeighbors(cur,i).filter(n=>cur.board[n].mine).length);cur.generated=true;cur.status='playing';cur.runningSince=nowISO()}
function revealMineFlood(cur,start){const stack=[start],seen=new Set();while(stack.length){const i=stack.pop();if(seen.has(i))continue;seen.add(i);const cell=cur.board[i];if(cell.flagged||cell.revealed||cell.mine)continue;cell.revealed=true;if(cell.adj===0)for(const n of mineNeighbors(cur,i))if(!cur.board[n].mine)stack.push(n)}}
function finishMine(cur,won){const M=mineData(),stats=M.stats;captureMineTime(cur);cur.status=won?'won':'lost';cur.runningSince=null;cur.completedAt=nowISO();stats.bestSeconds=stats.bestSeconds||{};if(won){stats.won=Number(stats.won||0)+1;const key=mineBestKey(cur),old=stats.bestSeconds[key];stats.bestSeconds[key]=old==null?cur.elapsedSeconds:Math.min(old,cur.elapsedSeconds);const preset=mineConfig(cur.difficulty);if(cur.mines===preset.mines){const legacy=stats.bestSeconds[cur.difficulty];stats.bestSeconds[cur.difficulty]=legacy==null?cur.elapsedSeconds:Math.min(legacy,cur.elapsedSeconds)}const reward=cur.difficulty==='easy'?8:cur.difficulty==='medium'?14:22;awardDecorCoins(reward,'扫雷胜利')}else stats.lost=Number(stats.lost||0)+1;M.history.unshift({id:cur.id,date:today(),difficulty:cur.difficulty,rows:cur.rows,cols:cur.cols,mines:cur.mines,won,seconds:cur.elapsedSeconds,moves:cur.moves});M.history=M.history.slice(0,20);toast(won?`扫雷成功！用时 ${formatTime(cur.elapsedSeconds)}`:'踩到地雷啦，再来一局！')}
async function revealMine(index){const cur=mineData().current;if(!cur||!['ready','playing'].includes(cur.status))return;const cell=cur.board[index];if(cell.flagged||cell.revealed)return;if(!cur.generated)generateMines(cur,index);captureMineTime(cur);cur.moves++;if(cur.board[index].mine){cur.board.forEach(c=>{if(c.mine)c.revealed=true});finishMine(cur,false);await persist('扫雷失败',true,true);return}revealMineFlood(cur,index);const won=cur.board.every(c=>c.mine||c.revealed);if(won)finishMine(cur,true);await persist(won?'完成扫雷':'扫雷翻格',won,won)}
async function flagMine(index){const cur=mineData().current;if(!cur||!['ready','playing'].includes(cur.status))return;const cell=cur.board[index];if(cell.revealed)return;cell.flagged=!cell.flagged;cur.moves++;await persist('扫雷插旗',false,false)}
async function resetMine(){const cur=mineData().current;if(!cur)return;if(!confirm('清空当前雷区并重新开始吗？'))return;createMineCurrent(cur.difficulty,false,cur.mines);await persist('重置扫雷',false,false)}
function renderMines(){const M=mineData(),cur=M.current,stats=M.stats||{};stats.bestSeconds=stats.bestSeconds||{};const best=cur?(stats.bestSeconds[mineBestKey(cur)]??stats.bestSeconds[cur.difficulty]):null;$('#mineStatus').innerHTML=[['已开局',stats.played||0],['已胜利',stats.won||0],['最佳用时',best==null?'—':formatTime(best)],['当前用时',cur?formatTime(mineElapsed(cur)):'00:00']].map(x=>`<div class="game-stat"><div class="label">${x[0]}</div><strong>${x[1]}</strong></div>`).join('');$('#mineFlagBtn').classList.toggle('flag-active',mineFlagMode);$('#mineFlagBtn').textContent=`🚩 插旗模式：${mineFlagMode?'开':'关'}`;
 if(!cur){syncMineCountInput(false);$('#mineGrid').innerHTML='';$('#mineMessage').textContent='点“新雷区”开始。第一次点击一定安全。'}else{const size=cur.cols>=16?22:cur.cols>=12?27:32;$('#mineDifficulty').value=cur.difficulty;$('#mineCount').max=mineCountLimit(cur.difficulty);$('#mineCount').value=cur.mines;$('#mineGrid').style.cssText=`--mine-size:${size}px;grid-template-columns:repeat(${cur.cols},var(--mine-size))`;$('#mineGrid').innerHTML=cur.board.map((c,i)=>{let text='',cls=['mine-cell'];if(c.revealed){cls.push('revealed');if(c.mine){cls.push('mine');text='💣'}else if(c.adj){cls.push(`n${c.adj}`);text=c.adj}}else if(c.flagged){cls.push('flagged');text='🚩'}return `<button class="${cls.join(' ')}" data-mine-cell="${i}" aria-label="${c.revealed?(c.mine?'地雷':c.adj?`周围${c.adj}颗雷`:'空格'):c.flagged?'已插旗':'未翻开'}">${text}</button>`}).join('');const flags=cur.board.filter(c=>c.flagged).length,revealed=cur.board.filter(c=>c.revealed&&!c.mine).length;const label=`${cur.rows}×${cur.cols} · ${cur.mines}雷`;$('#mineMessage').textContent=cur.status==='won'?`完成！${label}，用时 ${formatTime(cur.elapsedSeconds)}，共操作 ${cur.moves} 次。`:cur.status==='lost'?'踩到地雷了。可以重置本局或开启新雷区。':`${label}｜已翻 ${revealed} 格｜旗帜 ${flags}/${cur.mines}`}
 $('#mineHistory').innerHTML=(M.history||[]).map(h=>{const cfg=mineConfig(h.difficulty),rows=h.rows||cfg.rows,cols=h.cols||cfg.cols,mines=h.mines||cfg.mines;return `<div class="game-history-row"><div><strong>${h.won?'胜利':'未完成'} · ${rows}×${cols} · ${mines}雷</strong><br><small>${esc(h.date)} · ${h.moves}次操作</small></div><strong>${formatTime(h.seconds)}</strong></div>`}).join('')||'<div class="empty">完成第一局后，记录会出现在这里。</div>'}
function startMineClock(){clearInterval(mineTimer);mineTimer=setInterval(()=>{if(currentView==='brain'&&brainGame()==='minesweeper'&&mineData().current?.status==='playing'){const boxes=$$('#mineStatus .game-stat strong');if(boxes[3])boxes[3].textContent=formatTime(mineElapsed())}},1000)}


/* 餐厅与外卖打卡 */
let restaurantDraftPhotos=[];
function restaurantData(){
  state.modules=state.modules||{};
  if(!state.modules.restaurants||typeof state.modules.restaurants!=='object')state.modules.restaurants={enabled:true,items:[]};
  const R=state.modules.restaurants;R.enabled=true;R.items=Array.isArray(R.items)?R.items:[];return R
}
function normalizeRestaurantItem(r){
  r.restaurantName=String(r.restaurantName||r.name||'未命名餐厅');r.date=/^\d{4}-\d{2}-\d{2}$/.test(r.date||'')?r.date:today();r.channel=['堂食','外卖','自提','打包'].includes(r.channel)?r.channel:'堂食';r.amount=Math.max(0,Number(r.amount||0));r.companion=String(r.companion||'独自');r.cuisine=String(r.cuisine||'');r.rating=Math.min(5,Math.max(1,Number(r.rating||5)));r.dishes=Array.isArray(r.dishes)?r.dishes.filter(Boolean):String(r.dishes||'').split(/\n|,|，/).map(x=>x.trim()).filter(Boolean);r.tags=Array.isArray(r.tags)?r.tags.filter(Boolean):String(r.tags||'').split(/,|，/).map(x=>x.trim()).filter(Boolean);r.review=String(r.review||'');r.recommended=String(r.recommended||'');r.avoid=String(r.avoid||'');r.photos=Array.isArray(r.photos)?r.photos.filter(p=>typeof p==='string'&&p.startsWith('data:image/')).slice(0,4):[];r.ledgerRecordId=String(r.ledgerRecordId||'');return r
}
function restaurantLedgerRecord(r){return r.ledgerRecordId?state.ledger.records.find(x=>x.id===r.ledgerRecordId):null}
function restaurantShownAmount(r){const l=restaurantLedgerRecord(r);return l?Number(l.amount||0):Number(r.amount||0)}
function restaurantStars(n){return '★'.repeat(Math.max(1,Math.min(5,Math.round(Number(n)||1))))+'☆'.repeat(5-Math.max(1,Math.min(5,Math.round(Number(n)||1))))}
function restaurantSelectedMonth(){const el=$('#restaurantMonth');if(!el.value)el.value=monthNow();return el.value}
function renderRestaurantsHome(){const el=$('#homeRestaurantSummary');if(!el)return;const all=restaurantData().items.map(normalizeRestaurantItem);if(!all.length){el.textContent='把堂食、外卖和推荐菜都收进自己的味觉地图。';return}const latest=[...all].sort((a,b)=>String(b.date+b.updatedAt).localeCompare(String(a.date+a.updatedAt)))[0];el.textContent=`已经记录 ${all.length} 次用餐；最近一次是 ${latest.date} 的“${latest.restaurantName}”。`}
function renderRestaurants(){
  const R=restaurantData();R.items=R.items.map(normalizeRestaurantItem);const month=restaurantSelectedMonth(),channel=$('#restaurantChannelFilter').value,minRating=Number($('#restaurantRatingFilter').value||0),q=$('#restaurantSearch').value.trim().toLowerCase();const monthItems=R.items.filter(r=>r.date.startsWith(month));const total=monthItems.reduce((s,r)=>s+restaurantShownAmount(r),0),avgRating=monthItems.length?monthItems.reduce((s,r)=>s+r.rating,0)/monthItems.length:0,delivery=monthItems.filter(r=>r.channel==='外卖').length;const counts={};monthItems.forEach(r=>{if(r.restaurantName)counts[r.restaurantName]=(counts[r.restaurantName]||0)+1});const favorite=Object.entries(counts).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0];$('#restaurantKpis').innerHTML=[['本月打卡',`${monthItems.length}次`,`${delivery}次外卖`],['本月消费',money(total),monthItems.length?`平均 ${money(total/monthItems.length)}`:'尚无记录'],['平均口味',avgRating?`${avgRating.toFixed(1)}星`:'—',avgRating?restaurantStars(Math.round(avgRating)):'等待第一条评分'],['最常记录',favorite?favorite[0]:'—',favorite?`${favorite[1]}次`:'还没有常去的小店']].map(x=>`<article class="panel card kpi-card"><div class="label">${x[0]}</div><div class="value">${esc(x[1])}</div><div class="sub">${esc(x[2])}</div></article>`).join('');
  let items=R.items.filter(r=>r.date.startsWith(month)&&(!channel||r.channel===channel)&&(!minRating||r.rating>=minRating));if(q)items=items.filter(r=>`${r.restaurantName} ${r.cuisine} ${r.channel} ${r.companion} ${r.dishes.join(' ')} ${r.tags.join(' ')} ${r.review} ${r.recommended} ${r.avoid}`.toLowerCase().includes(q));items.sort((a,b)=>String(b.date+b.updatedAt).localeCompare(String(a.date+a.updatedAt)));$('#restaurantList').innerHTML=items.map(r=>{const ledger=restaurantLedgerRecord(r),tags=[r.cuisine,...r.tags].filter(Boolean),photos=r.photos.slice(0,4).map(p=>`<img src="${p}" alt="${esc(r.restaurantName)}的美食图片" loading="lazy">`).join('');return `<article class="restaurant-card"><div class="restaurant-head"><div><div class="restaurant-title">${esc(r.restaurantName)}</div><div class="restaurant-meta"><span>${esc(r.date)}</span><span>·</span><span>${esc(r.channel)}</span><span>·</span><span>${esc(r.companion)}</span></div></div><div><div class="restaurant-price">${money(restaurantShownAmount(r))}</div><div class="restaurant-stars" aria-label="${r.rating}星">${restaurantStars(r.rating)}</div></div></div>${tags.length?`<div class="restaurant-tags">${tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>`:''}${photos?`<div class="restaurant-gallery">${photos}</div>`:''}${r.dishes.length?`<div class="restaurant-copy"><strong>点单：</strong>${r.dishes.map(esc).join('、')}</div>`:''}${r.review?`<div class="restaurant-copy">${esc(r.review)}</div>`:''}${r.recommended||r.avoid?`<div class="restaurant-notes">${r.recommended?`<div class="restaurant-note-box recommend"><strong>推荐：</strong>${esc(r.recommended)}</div>`:''}${r.avoid?`<div class="restaurant-note-box avoid"><strong>避雷：</strong>${esc(r.avoid)}</div>`:''}</div>`:''}<div class="wish-foot">${ledger?`<span class="restaurant-linked">✓ 已关联 ${esc(ledger.date)} 账单</span>`:'<span class="sub" style="margin:0">尚未关联账单</span>'}<div class="restaurant-actions">${ledger?'<button class="icon-btn" disabled>已记账</button>':`<button class="icon-btn primary-action" data-restaurant-action="record" data-id="${r.id}">记入账本</button>`}<button class="icon-btn" data-restaurant-action="repeat" data-id="${r.id}">再去一次</button><button class="icon-btn" data-restaurant-action="edit" data-id="${r.id}">编辑</button><button class="icon-btn" data-restaurant-action="delete" data-id="${r.id}">删除</button></div></div></article>`}).join('')||'<div class="empty">这个月份还没有探店或外卖记录。</div>';renderRestaurantsHome()
}
