$('#freecellTop').onclick=async e=>{const free=e.target.closest('[data-fc-free]'),foundation=e.target.closest('[data-fc-foundation]'),cur=freecellData().current;if(!cur)return;if(free){const i=Number(free.dataset.fcFree);if(freecellSelected){if(freecellSelected.zone==='free'&&freecellSelected.index===i){freecellSelected=null;renderFreecell()}else await moveFreecellTo({zone:'free',index:i})}else if(cur.freecells[i])selectFreecellSource({zone:'free',index:i})}if(foundation&&freecellSelected)await moveFreecellTo({zone:'foundation',suit:foundation.dataset.fcFoundation})};
$('#freecellColumns').onclick=async e=>{const colEl=e.target.closest('[data-fc-column]'),card=e.target.closest('[data-fc-card]'),cur=freecellData().current;if(!cur||!colEl)return;const column=Number(colEl.dataset.fcColumn);if(!freecellSelected){if(card)selectFreecellSource({zone:'tableau',column,index:Number(card.dataset.fcIndex)});return}if(card&&freecellSelected.zone==='tableau'&&freecellSelected.column===column&&freecellSelected.index===Number(card.dataset.fcIndex)){freecellSelected=null;renderFreecell();return}await moveFreecellTo({zone:'tableau',column})};
