$('#mineCount').onchange=()=>syncMineCountInput(false);
$('#mineCount').onblur=()=>syncMineCountInput(false);
$('#newMineBtn').onclick=newMine;
$('#mineFlagBtn').onclick=()=>{mineFlagMode=!mineFlagMode;renderMines()};
$('#resetMineBtn').onclick=resetMine;
$('#mineGrid').onclick=async e=>{const b=e.target.closest('[data-mine-cell]');if(!b)return;const i=Number(b.dataset.mineCell);if(mineFlagMode)await flagMine(i);else await revealMine(i)};
$('#mineGrid').oncontextmenu=async e=>{const b=e.target.closest('[data-mine-cell]');if(!b)return;e.preventDefault();await flagMine(Number(b.dataset.mineCell))};
document.addEventListener('keydown',e=>{if(currentView!=='brain'||brainGame()!=='sudoku')return;if(/^[1-9]$/.test(e.key))setSudokuNumber(Number(e.key));if(e.key==='Backspace'||e.key==='Delete'||e.key==='0')setSudokuNumber(0)});

$('#petMain').onclick=async e=>{
 if(petDecorMoved){petDecorMoved=false;return}
 const main=e.target.closest('[data-pet-main]');if(main){openPetSetup();return}
 const scenePrev=e.target.closest('[data-pet-scene-prev]');if(scenePrev){const order=['forest','home','meadow','village'];const T=tamagotchiData();const idx=order.indexOf(T.scene||'forest');T.scene=order[(idx-1+order.length)%order.length];petGamePanel='';selectedPetDecorId='';await persist('切换树屋场景',false,false);return}
 const sceneNext=e.target.closest('[data-pet-scene-next]');if(sceneNext){const order=['forest','home','meadow','village'];const T=tamagotchiData();const idx=order.indexOf(T.scene||'forest');T.scene=order[(idx+1)%order.length];petGamePanel='';selectedPetDecorId='';await persist('切换树屋场景',false,false);return}
 const scene=e.target.closest('[data-pet-scene]');if(scene){tamagotchiData().scene=scene.dataset.petScene;petGamePanel='';selectedPetDecorId='';await persist('切换树屋场景',false,false);return}
 const close=e.target.closest('[data-pet-close]');if(close){petGamePanel='';selectedPetDecorId='';renderVillage();return}
 const panel=e.target.closest('[data-pet-panel]');if(panel){petGamePanel=petGamePanel===panel.dataset.petPanel?'':panel.dataset.petPanel;if(petGamePanel!=='decor')selectedPetDecorId='';renderVillage();return}
 const category=e.target.closest('[data-pet-category]');if(category){selectedPetCategory=category.dataset.petCategory;renderVillage();return}
 const decorateSelect=e.target.closest('[data-pet-decor-select]');if(decorateSelect){selectedPetDecorId=decorateSelect.dataset.petDecorSelect;renderVillage();return}
 const decorBuy=e.target.closest('[data-pet-decor-buy]');if(decorBuy){await buyDecor(decorBuy.dataset.petDecorBuy);return}
 const decorPlace=e.target.closest('[data-pet-decor-place]');if(decorPlace){await placeDecor(decorPlace.dataset.petDecorPlace);return}
 const decorAct=e.target.closest('[data-pet-decor-act]');if(decorAct){await petDecorAction(decorAct.dataset.petDecorAct);return}
 const decorItem=e.target.closest('[data-pet-decor-item]');if(decorItem&&petGamePanel==='decor'){selectedPetDecorId=decorItem.dataset.petDecorItem;renderVillage();return}
 const marry=e.target.closest('[data-pet-marry]');if(marry){e.preventDefault();e.stopPropagation();await marryPetResident(marry.dataset.petMarry);return}
 const hang=e.target.closest('[data-pet-hang]');if(hang){await petHangout(hang.dataset.petHang);return}
 const talk=e.target.closest('[data-pet-talk]');if(talk){await petTalk(talk.dataset.petTalk);return}
 const eventChoice=e.target.closest('[data-pet-event-choice]');if(eventChoice){petGamePanel='';await resolvePetEvent(eventChoice.dataset.petEventChoice);return}
 const family=e.target.closest('[data-pet-family]');if(family){await petFamilyAction(family.dataset.petFamily);return}
 const tool=e.target.closest('[data-pet-tool]');if(tool){selectedPetTool=selectedPetTool===tool.dataset.petTool?'':tool.dataset.petTool;renderVillage();return}
 const avatar=e.target.closest('[data-pet-avatar]');if(avatar){if(selectedPetTool)await petRunTool(selectedPetTool);else await petPat()}
};
$('#petMain').ondragstart=e=>{const tool=e.target.closest('[data-pet-tool]');if(tool&&!tool.disabled)e.dataTransfer.setData('text/pet-tool',tool.dataset.petTool)};
$('#petMain').ondragover=e=>{if(e.target.closest('[data-pet-dropzone]')){e.preventDefault();e.target.closest('[data-pet-dropzone]').classList.add('pet-drop-active')}};
$('#petMain').ondragleave=e=>{const z=e.target.closest('[data-pet-dropzone]');if(z)z.classList.remove('pet-drop-active')};
$('#petMain').ondrop=async e=>{const z=e.target.closest('[data-pet-dropzone]');if(!z)return;e.preventDefault();z.classList.remove('pet-drop-active');await petRunTool(e.dataTransfer.getData('text/pet-tool'))};
$('#petMain').onpointerdown=e=>{const item=e.target.closest('[data-pet-decor-item]');if(!item||petGamePanel!=='decor')return;const stage=e.target.closest('.pet-game-stage');if(!stage)return;selectedPetDecorId=item.dataset.petDecorItem;const d=decorSelected(tamagotchiData().scene||'forest');if(!d)return;petDecorMoved=false;petDecorDrag={id:d.id,stage,rect:stage.getBoundingClientRect(),pointerId:e.pointerId};item.classList.add('dragging');item.setPointerCapture?.(e.pointerId);e.preventDefault()};
function updatePetDecorFromPointer(e){if(!petDecorDrag)return;const d=decorSelected(tamagotchiData().scene||'forest');if(!d)return;const r=petDecorDrag.rect;const nx=Math.max(4,Math.min(96,((e.clientX-r.left)/r.width)*100));const ny=Math.max(8,Math.min(92,((e.clientY-r.top)/r.height)*100));d.x=nx;d.y=ny;const el=document.querySelector(`[data-pet-decor-item="${petDecorDrag.id}"]`);if(el){el.style.left=`${nx}%`;el.style.top=`${ny}%`;el.classList.add('selected')}}
$('#petMain').onpointermove=e=>{if(!petDecorDrag)return;petDecorMoved=true;updatePetDecorFromPointer(e)};
$('#petMain').onpointerup=async e=>{if(!petDecorDrag)return;const id=petDecorDrag.id;document.querySelector(`[data-pet-decor-item="${id}"]`)?.classList.remove('dragging');updatePetDecorFromPointer(e);petDecorDrag=null;await persist('移动场景摆设',false,false)};
$('#petMain').onpointercancel=()=>{if(!petDecorDrag)return;document.querySelector(`[data-pet-decor-item="${petDecorDrag.id}"]`)?.classList.remove('dragging');petDecorDrag=null;renderVillage()};
$('#petCare').onclick=async()=>{};$('#petEvent').onclick=async()=>{};$('#petResidents').onclick=async()=>{};$('#petFamily').onclick=async()=>{};
$('#petEmojiPicker').onclick=e=>{const b=e.target.closest('[data-pet-emoji]');if(b)setPetSetupEmoji(b.dataset.petEmoji)};
$('#petSetupForm').onsubmit=async e=>{e.preventDefault();await createTamagotchiPet()};
$('#ledgerMonth').onchange=renderAll;$('#ledgerTypeFilter').onchange=renderLedger;$('#ledgerPoolFilter').onchange=renderLedger;$('#ledgerSearch').oninput=renderLedger;$('#choreSearch').oninput=renderChores;$('#choreFilter').onchange=renderChores;
$('#editBudgetBtn').onclick=()=>{$('#budgetEditor').innerHTML=Object.entries(state.ledger.budgets).map(([k,v])=>`<div class="field"><label>${esc(k)}</label><input type="number" min="0" step="10" data-budget="${esc(k)}" value="${Number(v)}"></div>`).join('');$('#budgetDialog').showModal()};$('#saveBudgetBtn').onclick=async()=>{$$('#budgetEditor [data-budget]').forEach(i=>state.ledger.budgets[i.dataset.budget]=Math.max(0,Number(i.value)||0));$('#budgetDialog').close();initSelects();await persist('调整预算',true,true)};
$('#dailyBackupSwitch').onclick=async()=>{state.settings.autoDailyDownload=!state.settings.autoDailyDownload;$('#dailyBackupSwitch').classList.toggle('on',state.settings.autoDailyDownload);await persist('修改备份设置',true,true)};$('#everyChangeSwitch').onclick=async()=>{state.settings.everyChangeDownload=!state.settings.everyChangeDownload;$('#everyChangeSwitch').classList.toggle('on',state.settings.everyChangeDownload);await persist('修改备份设置',true,true)};
$('#importFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{await importBackup(f)}catch(err){alert(err.message)}finally{e.target.value=''}};$('#persistBtn').onclick=async()=>{try{const ok=await navigator.storage?.persist?.();toast(ok?'已获得持久存储权限':'浏览器未授予持久权限，请保留外部备份')}catch{toast('当前浏览器不支持该功能')}};$('#exportCsvBtn').onclick=exportCsv;
$('#snapshotList').onclick=async e=>{const b=e.target.closest('[data-restore-snapshot]');if(!b)return;const s=await idbGet('snapshots',b.dataset.restoreSnapshot);if(!s)return;if(confirm(`恢复到 ${new Date(s.at).toLocaleString('zh-CN')} 的状态吗？当前状态会先下载备份。`)){downloadBackup('恢复前保护备份');state=clone(s.data);await persist('恢复版本快照',false,true);initSelects();toast('已恢复版本')}};
init().catch(err=>{console.error(err);alert('应用启动失败：'+err.message)});
